import { useEffect, useState, type FormEvent } from "react";
import { getMaintenanceSettings, saveMaintenanceSettings } from "../api/client";
import type { AppConfig, MaintenanceSettingsResponse } from "../types/api";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

type MaintenancePaneProps = {
  refreshToken: number;
  onApplied: (config: AppConfig) => void;
};

export function MaintenancePane({ refreshToken, onApplied }: MaintenancePaneProps) {
  const [settings, setSettings] = useState<MaintenanceSettingsResponse | null>(null);
  const [draft, setDraft] = useState<AppConfig | null>(null);
  const [state, setState] = useState<"loading" | "idle" | "saving" | "saved" | "error">("loading");
  const [message, setMessage] = useState("");

  useEffect(() => {
    let cancelled = false;
    setState("loading");
    void getMaintenanceSettings().then((next) => {
      if (cancelled) return;
      setSettings(next);
      setDraft(next.values);
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      if (cancelled) return;
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load settings");
    });
    return () => { cancelled = true; };
  }, [refreshToken]);

  const reload = () => {
    setState("loading");
    void getMaintenanceSettings().then((next) => {
      setSettings(next);
      setDraft(next.values);
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load settings");
    });
  };

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings || !draft) return;
    setState("saving");
    setMessage("");
    void saveMaintenanceSettings(settings.revision, draft).then((next) => {
      setSettings(next);
      setDraft(next.values);
      onApplied(next.values);
      setState("saved");
      setMessage("Saved and applied to all connected clients.");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to save settings");
    });
  };

  return (
    <PaneFrame
      className="maintenance-frame"
      header={<PaneHeader
        title="Maintenance"
        meta="Shared frontend runtime settings"
        actions={<button type="button" className="maintenance-secondary-button" onClick={reload} disabled={state === "loading" || state === "saving"}>Reload</button>}
      />}
    >
      <form className="maintenance-form" onSubmit={submit}>
        <div className="maintenance-intro">Changes are validated by the server, persisted for the next restart, and applied immediately to every connected client.</div>
        {settings?.sections.map((section) => (
          <section key={section.id} className="maintenance-section">
            <div className="maintenance-section-copy">
              <h2>{section.label}</h2>
              {section.description && <p>{section.description}</p>}
            </div>
            <div className="maintenance-table-wrap">
              <table className="maintenance-table">
                <thead><tr><th>Parameter</th><th>Value</th><th>Range</th><th>Apply</th></tr></thead>
                <tbody>
                  {section.settings.map((setting) => (
                    <tr key={setting.key}>
                      <th scope="row"><span>{setting.label}</span>{setting.description && <small>{setting.description}</small>}</th>
                      <td>
                        {setting.type === "select" ? (
                          <select value={draft?.[setting.key] ?? ""} disabled={!draft || state === "saving"} onChange={(event) => setDraft((current) => current ? { ...current, [setting.key]: Number(event.target.value) } : current)}>
                            {setting.options?.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
                          </select>
                        ) : (
                          <input type="number" value={draft?.[setting.key] ?? ""} min={setting.min} max={setting.max} step={setting.step ?? 1} disabled={!draft || state === "saving"} onChange={(event) => setDraft((current) => current ? { ...current, [setting.key]: Number(event.target.value) } : current)} />
                        )}
                        {setting.unit && <span className="maintenance-unit">{setting.unit}</span>}
                      </td>
                      <td>{setting.min ?? "—"}–{setting.max ?? "—"}</td>
                      <td><span className={`maintenance-apply maintenance-apply-${setting.apply}`}>{setting.apply}</span></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>
        ))}
        <footer className="maintenance-actions">
          <span className={`maintenance-message maintenance-message-${state}`} role="status">{state === "loading" ? "Loading settings…" : message}</span>
          <button type="submit" className="maintenance-save-button" disabled={!draft || state === "loading" || state === "saving"}>{state === "saving" ? "Saving…" : "Save and apply"}</button>
        </footer>
      </form>
    </PaneFrame>
  );
}
export type NumericStat = {
  value?: number;
  avg?: number;
  min?: number;
  max?: number;
  count?: number;
};

export type MetricPoint = NumericStat & {
  time: number;
};

export type TimelineSegment = {
  start: number;
  end: number | null;
};

export type TimelineWindow = {
  from: number;
  to: number;
};

export type TimelineRow = {
  rowType: "stream" | "flow";
  streamKey: string;
  flowKey?: string;
  parentStreamKey?: string;
  kind: string;
  proto: string;
  label: string;
  role?: string;
  endpointSrc?: string;
  endpointDst?: string;
  interfaceId?: number;
  interfaceName?: string;
  active: boolean;
  firstSeen: number;
  lastSeen: number;
  segments: TimelineSegment[];
};

export type TimelineViewResponse = {
  rows: TimelineRow[];
  window: TimelineWindow;
  available: TimelineWindow;
  source: "live" | "history";
};

export type FlowListItem = {
  flowKey: string;
  role: string;
  label: string;
  active: boolean;
  interfaceId?: number;
  interfaceName?: string;
  endpointSrc?: string;
  endpointDst?: string;
  lastSeen: number;
  bitrate: NumericStat;
  sparkline: number[];
  overview: OverviewStats;
};

export type StreamListItem = {
  streamKey: string;
  kind: string;
  proto: string;
  label: string;
  endpointA?: string;
  endpointB?: string;
  sessionDst?: string;
  streamId?: string;
  interfaceId?: number;
  interfaceName?: string;
  active: boolean;
  lastSeen: number;
  flowCount: number;
  flowRoles: string[];
  bitrate: NumericStat;
  sparkline: number[];
  overview: OverviewStats;
  flows: FlowListItem[];
};

export type OverviewStats = {
  gap: number;
  dup: number;
  reorder: number;
  events: number;
};

export type FlowState = {
  flowKey: string;
  role: string;
  label: string;
  active: boolean;
  interfaceId?: number;
  interfaceName?: string;
  endpointSrc?: string;
  endpointDst?: string;
  lastSeen: number;
  metrics: Record<string, NumericStat>;
};

export type StreamState = Omit<StreamListItem, "flows"> & {
  flows: FlowState[];
};

export type MetricDescriptor = {
  key: string;
  label: string;
  unit?: string;
  category: "primary" | "secondary" | "stat";
  display: "range-line" | "line" | "stat";
  priority: number;
};

export type InterfaceCounters = {
  bytes: NumericStat;
  packets: NumericStat;
  errors: NumericStat;
  dropped: NumericStat;
};

export type InterfaceLinkInfo = {
  speedMbps?: number;
  duplex?: string;
  operstate?: string;
  carrier?: boolean;
  mtu?: number;
  mac?: string;
};

export type InterfaceRateInfo = {
  bitrateBps?: number;
  utilization?: number;
  headroomBps?: number;
};

export type InterfaceListItem = {
  key: string;
  interfaceId?: number;
  name: string;
  observed: boolean;
  available: boolean;
  link?: InterfaceLinkInfo;
  lastSeen?: number;
  rx: InterfaceCounters;
  tx: InterfaceCounters;
  rxRate?: InterfaceRateInfo;
  txRate?: InterfaceRateInfo;
  rxBitrate: NumericStat;
  txBitrate: NumericStat;
  rxSparkline: number[];
  txSparkline: number[];
  streamCount: number;
};

export type InterfaceMetricsResponse = {
  key: string;
  interfaceId?: number;
  name: string;
  windowSec: number;
  metrics: Record<string, TimeSeriesMetric>;
};

export type TimeSeriesMetric = {
  key: string;
  label: string;
  unit?: string;
  points: MetricPoint[];
};

export type FlowMetricsResponse = {
  flowKey: string;
  role: string;
  label: string;
  endpointSrc?: string;
  endpointDst?: string;
  metrics: Record<string, TimeSeriesMetric>;
};

export type StreamMetricsResponse = {
  streamKey: string;
  windowSec: number;
  streamBitrate: TimeSeriesMetric;
  flows: FlowMetricsResponse[];
  descriptors: MetricDescriptor[];
};

export type EventLogItem = {
  id: string;
  time: number;
  type: string;
  level: "info" | "warn" | "error";
  scope: "system" | "stream" | "flow";
  proto?: string;
  interfaceId?: number;
  streamKey?: string;
  flowKey?: string;
  targetLabel?: string;
  message: string;
  detail?: unknown;
};

export type TopologyAlertSummary = {
  state?: string;
  severity?: string;
  count?: number;
  alerts?: unknown[];
};

export type TopologyNode = {
  id: string;
  type: string;
  label?: string;
  host?: string;
  port?: number;
  transport?: string;
  alert?: TopologyAlertSummary;
import type { AppConfig, MaintenanceSettingsResponse, BootstrapResponse, EventLogItem, InterfaceListItem, InterfaceMetricsResponse, StreamListItem, StreamMetricsResponse, StreamState, Summary, TimelineViewResponse, DashboardLayout, StreamsSnapshotResponse, TopologySnapshot } from "../types/api";

export type MetricsRangeQuery = {
  windowSec?: number;
  from?: number;
  to?: number;
  resolutionSec?: number;
};

export type TimelineRangeQuery = {
  from?: number;
  to?: number;
  includeFlows?: boolean;
};

export async function getDashboardLayouts(): Promise<DashboardLayout[]> {
  return getJson("/api/dashboard-layouts");
}

export async function saveDashboardLayouts(layouts: DashboardLayout[]): Promise<DashboardLayout[]> {
  const response = await fetch("/api/dashboard-layouts", {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(layouts)
  });
  if (!response.ok) throw new Error(`${response.status} ${response.statusText}`);
  return response.json() as Promise<DashboardLayout[]>;
}

export async function getStreams(): Promise<StreamListItem[]> {
  return getJson("/api/streams");
}

export async function getStreamsSnapshotAt(timeSec: number): Promise<StreamsSnapshotResponse> {
  return getJson(`/api/streams?time=${encodeURIComponent(String(timeSec))}`);
}

export async function getAppConfig(): Promise<AppConfig> {
  return getJson("/api/config");
}

export async function getMaintenanceSettings(): Promise<MaintenanceSettingsResponse> {
  return getJson("/api/maintenance/frontend-settings");
}

export async function saveMaintenanceSettings(revision: number, values: AppConfig): Promise<MaintenanceSettingsResponse> {
  const response = await fetch("/api/maintenance/frontend-settings", {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ revision, values })
  });
  if (!response.ok) {
    const body = await response.json().catch(() => undefined) as { error?: string } | undefined;
    throw new Error(body?.error ?? "Request failed");
  }
  return response.json() as Promise<MaintenanceSettingsResponse>;
}

export async function getBootstrap(): Promise<BootstrapResponse> {
  return getJson("/api/bootstrap");
}

export async function getTopology(timeSec?: number): Promise<TopologySnapshot> {
  const suffix = timeSec !== undefined ? `?time=${encodeURIComponent(String(timeSec))}` : "";
  return getJson(`/api/topology${suffix}`);
}

export async function getTimeline(query: TimelineRangeQuery = {}): Promise<TimelineViewResponse> {
  const params = new URLSearchParams();
  if (query.from !== undefined) params.set("from", String(query.from));
  if (query.to !== undefined) params.set("to", String(query.to));
  if (query.includeFlows !== undefined) params.set("includeFlows", query.includeFlows ? "1" : "0");
  const suffix = params.toString() ? `?${params.toString()}` : "";
  return getJson(`/api/timeline${suffix}`);
}

export async function getInterfaces(): Promise<InterfaceListItem[]> {
  return getJson("/api/interfaces");
}

export async function getInterfaceMetrics(interfaceId: number, windowSec = 300): Promise<InterfaceMetricsResponse> {
  return getJson(`/api/interfaces/${interfaceId}/metrics?windowSec=${windowSec}`);
}

export async function getInterfaceMetricsByKey(key: string, query: number | MetricsRangeQuery = 300): Promise<InterfaceMetricsResponse> {
  const params = new URLSearchParams();
  if (typeof query === "number") params.set("windowSec", String(query));
  else {
    if (query.windowSec !== undefined) params.set("windowSec", String(query.windowSec));
    if (query.from !== undefined) params.set("from", String(query.from));
    if (query.to !== undefined) params.set("to", String(query.to));
  }
  return getJson(`/api/interfaces/by-key/${encodeURIComponent(key)}/metrics?${params.toString()}`);
}

export async function getSummary(): Promise<Summary> {
  return getJson("/api/summary");
}

export async function getStream(streamKey: string): Promise<StreamState> {
  return getJson(`/api/streams/${encodeURIComponent(streamKey)}`);
}

export async function getStreamMetrics(streamKey: string, query: number | MetricsRangeQuery = 300): Promise<StreamMetricsResponse> {
  const params = new URLSearchParams();
  if (typeof query === "number") {
    params.set("windowSec", String(query));
  } else {
    if (query.windowSec !== undefined) params.set("windowSec", String(query.windowSec));
    if (query.from !== undefined) params.set("from", String(query.from));
    if (query.to !== undefined) params.set("to", String(query.to));
    if (query.resolutionSec !== undefined) params.set("resolutionSec", String(query.resolutionSec));
  }
  return getJson(`/api/streams/${encodeURIComponent(streamKey)}/metrics?${params.toString()}`);
}

export async function getEvents(params: {
  streamKey?: string;
  flowKey?: string;
  interfaceId?: number;
  limit?: number;
  from?: number;
  to?: number;
  proto?: string;
  level?: "info" | "warn" | "error";
  type?: string;
} = {}): Promise<EventLogItem[]> {
  const query = new URLSearchParams();
  if (params.streamKey) query.set("streamKey", params.streamKey);
  if (params.flowKey) query.set("flowKey", params.flowKey);
  if (params.interfaceId !== undefined) query.set("interfaceId", String(params.interfaceId));
  if (params.from !== undefined) query.set("from", String(params.from));
  if (params.to !== undefined) query.set("to", String(params.to));
  if (params.proto) query.set("proto", params.proto);
  if (params.level) query.set("level", params.level);
  if (params.type) query.set("type", params.type);
  if (params.limit) query.set("limit", String(params.limit));
  const suffix = query.toString() ? `?${query.toString()}` : "";
  return getJson(`/api/events${suffix}`);
}
