      if (setting.max !== undefined && value > setting.max) throw new SettingsValidationError(` must be at most `);
      if (setting.options && !setting.options.some((option) => option.value === value)) throw new SettingsValidationError(` is not an allowed value`);
      result[setting.key] = value;
    }
    return result as RuntimeSettings;
