const r = await tools.exec_command({"cmd":"perl -0pi -e 's/broadcastConfig\(config: \{ lostRetentionSec: number; historyWindowSec: number; staleAfterSec: number \}\)/broadcastConfig(config: { lostRetentionSec: number; historyWindowSec: number; staleAfterSec: number; diagnosticLog: boolean })/' fe/server/src/ws/socketServer.ts
perl -0pi -e 's/(                        \{setting\.type === "select" \? \([\s\S]*?                        \) : \(\n                          <input type="number" value=\{draft\?\.\[setting\.key\] \?\? ""\} min=\{setting\.min\} max=\{setting\.max\} step=\{setting\.step \?\? 1\} disabled=\{!draft \|\| state === "saving"\} onChange=\{\(event\) => setDraft\(\(current\) => current \? \{ \.\.\.current, \[setting\.key\]: Number\(event\.target\.value\) \} : current\)\} \/>\n                        \)\})/                        {setting.type === "boolean" ? (\n                          <button\n                            type="button"\n                            role="switch"\n                            aria-checked={Boolean(draft?.[setting.key])}\n                            className={`maintenance-switch ${draft?.[setting.key] ? "is-on" : "is-off"}`}\n                            disabled={!draft || state === "saving"}\n                            onClick={() => setDraft((current) => current ? { ...current, [setting.key]: !current[setting.key] } : current)}\n                          >\n                            <span className="maintenance-switch-track" aria-hidden="true"><span className="maintenance-switch-thumb" /></span>\n                            <span>{draft?.[setting.key] ? "On" : "Off"}</span>\n                          </button>\n                        ) : setting.type === "select" ? (\n                          <select value={String(draft?.[setting.key] ?? "")} disabled={!draft || state === "saving"} onChange={(event) => setDraft((current) => current ? { ...current, [setting.key]: Number(event.target.value) } : current)}>\n                            {setting.options?.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}\n                          </select>\n                        ) : (\n                          <input type="number" value={String(draft?.[setting.key] ?? "")} min={setting.min} max={setting.max} step={setting.step ?? 1} disabled={!draft || state === "saving"} onChange={(event) => setDraft((current) => current ? { ...current, [setting.key]: Number(event.target.value) } : current)} />\n                        )}/' fe/client/src/components/MaintenancePane.tsx
perl -0pi -e 's/<td>\{setting\.min \?\? "—"\}–\{setting\.max \?\? "—"\}<\/td>/<td>{setting.type === "boolean" ? "—" : `${setting.min ?? "—"}–${setting.max ?? "—"}`}</td>/' fe/client/src/components/MaintenancePane.tsx
tee -a fe/client/src/styles/maintenance.css >/dev/null <<'EOF'

.maintenance-switch {
  display: inline-flex;
  min-width: 76px;
  min-height: var(--control-height);
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 9px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  background: var(--surface-muted);
  color: var(--muted);
  cursor: pointer;
  font-size: var(--font-size-xs);
  font-weight: 700;
}

.maintenance-switch-track {
  display: inline-flex;
  width: 28px;
  height: 16px;
  align-items: center;
  padding: 2px;
  border-radius: 999px;
  background: var(--line-strong);
  transition: background-color .15s ease;
}

.maintenance-switch-thumb {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--surface);
  box-shadow: var(--shadow-sm);
  transition: transform .15s ease;
}

.maintenance-switch.is-on {
  border-color: var(--success);
  background: var(--success-soft);
  color: var(--success);
}

.maintenance-switch.is-on .maintenance-switch-track {
  background: var(--success);
}

.maintenance-switch.is-on .maintenance-switch-thumb {
  transform: translateX(12px);
}

.maintenance-switch:disabled {
  cursor: wait;
  opacity: .6;
}
EOF
