#ifndef ALERT_EVALUATOR_H
#define ALERT_EVALUATOR_H

#include <filesystem>
#include <map>
#include <optional>
#include <string>
#include <vector>

#include "event.h"
#include "json.h"

class alert_evaluator {
public:
	enum class rule_type {
		threshold,
		counter_delta,
	};

	enum class compare_op {
		gt,
		ge,
		lt,
		le,
		eq,
		ne,
	};

	struct rule {
		std::string id;
		std::string target{"any"};
		std::string proto;
		std::string metric;
		rule_type type{rule_type::threshold};
		compare_op op{compare_op::gt};
		double error_threshold{0.0};
		double recover_threshold{0.0};
		double delta_threshold{0.0};
		double recover_after_sec{3.0};
		std::string severity{"warning"};
		bool enabled{true};
	};

	explicit alert_evaluator(event_sink &events);

	int load(const std::filesystem::path &path);
	bool empty() const noexcept { return m_rules.empty(); }
	void evaluate(double now, const json::array_t &metrics, const json::array_t &interfaces);
	json::array_t active_alerts() const;

private:
	struct state {
		bool active{false};
		bool has_last_value{false};
		double last_value{0.0};
		double last_error_time{0.0};
		double last_seen_time{0.0};
		json source{json::object()};
		json detail{json::object()};
	};

	event_sink &m_events;
	std::vector<rule> m_rules;
	std::map<std::string, state> m_states;

	void evaluate_entry(double now, const rule &r, const json &entry, bool is_interface);
	void evaluate_threshold(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, state &s, double value);
	void evaluate_counter_delta(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, state &s, double value);
	void emit_alert(double now, const rule &r, const json &entry, bool is_interface, std::string action, double value, json detail);
	void update_active_state(double now, const rule &r, const json &entry, bool is_interface, state &s, double value, json detail);

	static std::optional<double> metric_value(const json &entry, const std::string &path);
	static bool compare(double lhs, compare_op op, double rhs);
	static bool matches_target(const rule &r, const json &entry, bool is_interface);
	static std::string make_state_key(const rule &r, const json &entry, bool is_interface);
	static json make_target_source(const rule &r, const json &entry, bool is_interface);
	static rule_type parse_rule_type(const std::string &value);
	static compare_op parse_compare_op(const std::string &value);
};

#endif /* ALERT_EVALUATOR_H */
import { createHash } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";

export type AlertTarget = "any" | "flow" | "stream" | "interface";
export type AlertRuleType = "threshold" | "counter_delta";
export type AlertOperator = ">" | ">=" | "<" | "<=" | "==" | "!=";

export type AlertRule = {
  id: string;
  enabled?: boolean;
  target?: AlertTarget;
  proto?: string;
  metric: string;
  type?: AlertRuleType;
  operator?: AlertOperator;
  error_threshold?: number;
  recover_threshold?: number;
  delta_threshold?: number;
  recover_after_sec?: number;
  severity?: string;
};

export type AlertsDocument = { _note?: string; alerts: AlertRule[] };
export type AlertMetricDefinition = { key: string; description?: string; unit?: string; preview: boolean };
export type AlertsResponse = {
  revision: string;
  path: string;
  document: AlertsDocument;
  metrics: AlertMetricDefinition[];
  protocols: string[];
  apply: "restart_required";
};

export class AlertsConflictError extends Error {}
export class AlertsValidationError extends Error {}

export class AlertsSettings {
  constructor(private readonly stmConfigFile: string) {}

  async get(): Promise<AlertsResponse> {
    const configured = await this.readConfiguredAlerts();
    const schemaText = await readFile(this.schemaFile(), "utf8");
    const document = validateDocument(parseJson(configured.alertsText, "alerts config"));
    const schema = parseSchema(parseJson(schemaText, "alerts schema"));
    return {
      revision: revisionOf(configured.stmConfigText, configured.alertsText, schemaText),
      path: configured.relativePath,
      document,
      metrics: schema.metrics,
      protocols: schema.protocols,
      apply: "restart_required"
    };
  }

  async update(input: { revision: unknown; document: unknown }): Promise<AlertsResponse> {
    const current = await this.get();
    if (typeof input.revision !== "string" || input.revision !== current.revision) {
      throw new AlertsConflictError("alerts config changed on the server; reload before applying");
    }
    const document = validateDocument(input.document, current.metrics, current.protocols);
    const configured = await this.readConfiguredAlerts();
    await atomicWrite(configured.alertsFile, JSON.stringify(document, null, 2) + "\n");
    return this.get();
  }

  private async readConfiguredAlerts() {
    const stmConfigText = await readFile(this.stmConfigFile, "utf8");
    const stmConfig = parseObject(stmConfigText, "STM config");
    const configs = stmConfig.configs && typeof stmConfig.configs === "object" && !Array.isArray(stmConfig.configs)
      ? stmConfig.configs as Record<string, unknown> : undefined;
    const configuredPath = configs?.alerts ?? configs?.alert_config;
    if (typeof configuredPath !== "string" || !configuredPath.trim()) {
      throw new AlertsValidationError("configs.alerts must be a non-empty relative path");
    }
    const relativePath = validateRelativePath(configuredPath);
    const alertsFile = path.resolve(path.dirname(this.stmConfigFile), relativePath);
    const alertsText = await readFile(alertsFile, "utf8");
    return { stmConfigText, relativePath, alertsFile, alertsText };
  }

