#ifndef PROTOCOL_MAP_H
#define PROTOCOL_MAP_H

#include <filesystem>
#include <cstdint>
#include <string>
#include <string_view>
#include <vector>

#include "endpoint.h"
#include "json.h"
#include "tsv.h"

class protocol_map {
public:
	enum class observe_mode {
		all,
		configured_only,
		configured_plus_other,
	};

	struct vlan_match {
		enum class mode {
			any,
			untagged,
			id,
		};

		mode type{mode::any};
		std::string id;
	};

	struct rule {
		std::string proto;
		bool enabled{true};
		std::string stream_name;
		std::vector<std::string> endpoints;
		std::vector<std::string> hosts;
		std::vector<std::string> decode_as;
		bool fec{false};
		bool observe{true};
		vlan_match vlan;
	};

	int load(const std::filesystem::path &path);

	const std::vector<rule>& rules() const noexcept { return m_rules; }
	const std::vector<std::string>& decode_as_rules() const noexcept { return m_decode_as_rules; }
	observe_mode observation_mode() const noexcept { return m_observe_mode; }
	bool should_observe(std::string_view proto, const ip_endpoint &src, const ip_endpoint &dst, const tsv::vlan_info &vlan, std::string_view host = {}) const;
	bool has_observable_host_rule(std::string_view proto, const tsv::vlan_info &vlan) const;
	const std::vector<ip_endpoint>& rtp_fec_base_endpoints() const noexcept { return m_rtp_fec_base_endpoints; }
	bool empty() const noexcept { return m_rules.empty(); }

private:
	observe_mode m_observe_mode{observe_mode::all};
	std::vector<rule> m_rules;
	std::vector<std::string> m_decode_as_rules;
	std::vector<ip_endpoint> m_rtp_fec_base_endpoints;

	static std::vector<std::string> read_string_or_array(const json &j, const char *key);
	static bool read_bool(const json &j, const char *key, bool fallback);
	static observe_mode read_observe_mode(const json &j);
	static vlan_match read_vlan_match(const json &j);
	static bool endpoint_port(const std::string &endpoint, unsigned &port);
	static bool parse_endpoint(const std::string &endpoint, ip_endpoint &out);
	static bool auto_decode_as(std::string_view proto, unsigned port, std::string &out);
	static bool proto_matches(std::string_view rule_proto, std::string_view observed_proto);
	static bool is_dedicated_proto(std::string_view proto);
	static bool vlan_matches(const vlan_match &rule_vlan, const tsv::vlan_info &packet_vlan);
	static bool endpoint_matches(const rule &r, const ip_endpoint &candidate);
	static bool endpoint_matches(const rule &r, const ip_endpoint &configured, const ip_endpoint &candidate);
	static bool host_matches(const rule &r, std::string_view host);
	void add_decode_as(std::string value);
};

#endif /* PROTOCOL_MAP_H */
		std::cerr << "protocol_map: failed to parse " << path << ": " << e.what() << std::endl;
		return -1;
	}

	m_observe_mode = read_observe_mode(root);

	if(!root.is_object() || !root.contains("protocols") || !root["protocols"].is_array()) {
		std::cerr << "protocol_map: root.protocols must be an array" << std::endl;
		return -1;
	}

	for(const auto &entry : root["protocols"]) {
		if(!entry.is_object()) {
			std::cerr << "protocol_map: protocol entry must be an object" << std::endl;
			return -1;
		}
		if(!entry.contains("proto") || !entry["proto"].is_string()) {
			std::cerr << "protocol_map: protocol entry requires string proto" << std::endl;
			return -1;
		}

		rule r;
		r.proto = entry["proto"].get<std::string>();
		r.enabled = read_bool(entry, "enabled", true);
		if(entry.contains("stream_name") && entry["stream_name"].is_string()) {
			r.stream_name = entry["stream_name"].get<std::string>();
		}
		r.endpoints = read_string_or_array(entry, "endpoints");
		r.hosts = read_string_or_array(entry, "hosts");
		{
			auto domains = read_string_or_array(entry, "domains");
			r.hosts.insert(r.hosts.end(), domains.begin(), domains.end());
		}
		r.decode_as = read_string_or_array(entry, "decode_as");
		r.fec = read_bool(entry, "fec", false);
		r.observe = read_bool(entry, "observe", true);
		r.vlan = read_vlan_match(entry);

		// Disabled rules remain in the source document for later re-enabling, but
		// deliberately contribute no runtime classification or observation state.
		if(!r.enabled) {
			continue;
		}

		for(const auto &decode : r.decode_as) {
			add_decode_as(decode);
		}

		if(r.decode_as.empty()) {
			for(const auto &endpoint : r.endpoints) {
				unsigned port = 0;
				if(!endpoint_port(endpoint, port)) {
					std::cerr << "protocol_map: invalid endpoint " << endpoint << std::endl;
					return -1;
				}

				const bool expand_rtp_fec = upper(r.proto) == "RTP" && r.fec;
				const unsigned decode_count = expand_rtp_fec ? 3U : 1U;
				for(unsigned n = 0; n < decode_count; ++n) {
					const unsigned decode_port = port + n * 2U;
					if(decode_port > 65535U) {
						std::cerr << "protocol_map: RTP FEC endpoint port overflow " << endpoint << std::endl;
						return -1;
					}

					std::string decode;
					if(auto_decode_as(r.proto, decode_port, decode)) {
						add_decode_as(std::move(decode));
					}
					else {
						std::cerr << "protocol_map: no auto decode-as rule for proto "
						          << r.proto << " endpoint " << endpoint << std::endl;
						return -1;
					}
				}
			}
		}

		if(upper(r.proto) == "RTP" && r.fec) {
			for(const auto &endpoint : r.endpoints) {
				ip_endpoint base{};
				if(!parse_endpoint(endpoint, base)) {
					std::cerr << "protocol_map: invalid RTP FEC base endpoint " << endpoint << std::endl;
					return -1;
				}
				m_rtp_fec_base_endpoints.push_back(base);
			}
		}

		m_rules.push_back(std::move(r));
	}

	return 0;
}


