class expirable {
public:
    expirable() = default;
    virtual ~expirable() = default;

    void touch(double now) noexcept {
        m_last_seen = now;
        m_seen = true;
    }

    double last_seen() const noexcept {
        return m_last_seen;
    }

    bool seen() const noexcept {
        return m_seen;
    }

    bool expired(double now, double timeout_sec) const noexcept {
        return m_seen && (now - m_last_seen) >= timeout_sec;
    }

private:
    double m_last_seen = 0.0;
    bool   m_seen = false;
};

