export type AlertRule = { id: string; enabled?: boolean; target?: AlertTarget; proto?: string; metric: string; type?: AlertRuleType; operator?: AlertOperator; error_threshold?: number; recover_threshold?: number; delta_threshold?: number; recover_after_sec?: number; severity?: string; };
export type AlertsDocument = { _note?: string; alerts: AlertRule[]; };
export type AlertMetricDefinition = { key: string; description?: string; unit?: string; preview: boolean; };
export type AlertsResponse = { revision: string; path: string; document: AlertsDocument; metrics: AlertMetricDefinition[]; protocols: string[]; apply: "restart_required"; };

