	return true;
}

bool protocol_map::auto_decode_as(std::string_view proto, unsigned port, std::string &out) {
	const std::string p = upper(proto);
	if(p == "SRT") {
		out = "udp.port==" + std::to_string(port) + ",srt";
		return true;
	}
	if(p == "RTP") {
		out = "udp.port==" + std::to_string(port) + ",rtp";
		return true;
	}
	if(p == "RTMP") {
		out = "tcp.port==" + std::to_string(port) + ",rtmpt";
		return true;
	}
	if(p == "HTTP" || p == "HLS") {
		out = "tcp.port==" + std::to_string(port) + ",http";
		return true;
	}
	return false;
}

void protocol_map::add_decode_as(std::string value) {
	if(value.empty()) {
		return;
	}
	if(std::find(m_decode_as_rules.begin(), m_decode_as_rules.end(), value) != m_decode_as_rules.end()) {
		return;
	}
	m_decode_as_rules.push_back(std::move(value));
}


bool protocol_map::proto_matches(std::string_view rule_proto, std::string_view observed_proto) {
	const std::string rule = upper(rule_proto);
	const std::string observed = upper(observed_proto);
	if(rule == observed) {
		return true;
	}
	return (rule == "HLS" && observed == "HTTP") ||
	       (rule == "HTTP" && observed == "HLS") ||
	       ((rule == "HLS" || rule == "HTTP") && is_tls_proto(observed_proto)) ||
	       (rule == "RTMP" && observed == "RTMPT") ||
	       (rule == "RTMPT" && observed == "RTMP");
}

bool protocol_map::is_dedicated_proto(std::string_view proto) {
	const std::string p = upper(proto);
	return p == "RTP" || p == "SRT" || p == "HTTP" || p == "HLS" || p == "RTMP" || p == "RTMPT";
}

bool protocol_map::vlan_matches(const vlan_match &rule_vlan, const tsv::vlan_info &packet_vlan) {
	switch(rule_vlan.type) {
	case vlan_match::mode::any:
		return true;
	case vlan_match::mode::untagged:
		return packet_vlan.empty();
	case vlan_match::mode::id:
		return packet_vlan.id == rule_vlan.id;
	}
	return false;
}

bool protocol_map::endpoint_matches(const rule &r, const ip_endpoint &configured, const ip_endpoint &candidate) {
	if(configured.addr == candidate.addr && configured.port == candidate.port) {
		return true;
	}

	if(!(upper(r.proto) == "RTP" && r.fec)) {
		return false;
	}
	if(!(configured.addr == candidate.addr)) {
		return false;
	}
	if(candidate.port < configured.port) {
		return false;
	}

	const auto offset = static_cast<unsigned>(candidate.port - configured.port);
	return offset == 2U || offset == 4U;
}

bool protocol_map::endpoint_matches(const rule &r, const ip_endpoint &candidate) {
	for(const auto &endpoint : r.endpoints) {
		ip_endpoint configured{};
		if(!parse_endpoint(endpoint, configured)) {
			continue;
		}
		if(endpoint_matches(r, configured, candidate)) {
			return true;
		}
	}
	return false;
}

bool protocol_map::host_matches(const rule &r, std::string_view host) {
	if(host.empty()) {
		return false;
	}

	const auto observed = lower_host(host);
	if(observed.empty()) {
		return false;
	}

	for(const auto &configured_host : r.hosts) {
		const auto configured = lower_host(configured_host);
		if(configured.empty()) {
			continue;
		}
		if(configured == observed) {
			return true;
		}
		if(configured.size() > 2 && configured[0] == '*' && configured[1] == '.') {
			const auto suffix = configured.substr(1);
			if(observed.size() >= suffix.size() &&
			   observed.compare(observed.size() - suffix.size(), suffix.size(), suffix) == 0) {
				return true;
			}
		}
	}

	return false;
}

bool protocol_map::should_observe(std::string_view proto,
                                  const ip_endpoint &src,
                                  const ip_endpoint &dst,
                                  const tsv::vlan_info &vlan,
                                  std::string_view host) const {
	if(m_observe_mode == observe_mode::all) {
		return true;
	}
	if(m_observe_mode == observe_mode::configured_plus_other && !is_dedicated_proto(proto)) {
		return true;
	}

	for(const auto &r : m_rules) {
		if(!r.observe) {
			continue;
		}
		if(!proto_matches(r.proto, proto)) {
			continue;
		}
		if(!vlan_matches(r.vlan, vlan)) {
			continue;
		}
		if(endpoint_matches(r, src) || endpoint_matches(r, dst) || host_matches(r, host)) {
			return true;
		}
	}

	return false;
}


bool protocol_map::has_observable_host_rule(std::string_view proto, const tsv::vlan_info &vlan) const {
	for(const auto &r : m_rules) {
		if(!r.observe || r.hosts.empty()) {
			continue;
		}
		if(!proto_matches(r.proto, proto)) {
			continue;
		}
		if(!vlan_matches(r.vlan, vlan)) {
			continue;
		}
		return true;
	}
	return false;
}
#include "stream_registry.h"

#include <utility>

#include "event.h"

stream_registry::protocol_configs stream_registry::make_protocol_configs(const protocol_map &protocols) {
	protocol_configs cfg{};
	cfg.rtp.fec_base_endpoints = protocols.rtp_fec_base_endpoints();
	return cfg;
}

stream_registry::stream_registry(const protocol_map &protocols, event_sink &events)
	: m_protocols(protocols) {
	auto cfg = make_protocol_configs(protocols);

	m_srt = std::make_unique<srt::streams>(cfg.srt, events);
	m_rtp = std::make_unique<rtp::streams>(cfg.rtp, events);
	m_rtmp = std::make_unique<rtmp::streams>(cfg.rtmp, events);
	m_hls = std::make_unique<hls::streams>(cfg.hls, events);
	m_other = std::make_unique<other::streams>(cfg.other, events);

	m_all_streams = { m_srt.get(), m_rtp.get(), m_rtmp.get(), m_hls.get(), m_other.get() };
	// Preserve the existing monitor output order. RTMP dispatch exists, but metrics/list output was not emitted before this refactor.
	m_output_streams = { m_srt.get(), m_rtp.get(), m_hls.get(), m_other.get() };

	dispatch_adapter_context dispatch_ctx{
		.protocols = m_protocols,
		.other_fallback = *m_other,
	};
	for(auto *stream : m_all_streams) {
		register_stream(*stream);
		if(auto adapter = stream->make_dispatch_adapter(dispatch_ctx)) {
			m_dispatch_adapters.emplace_back(std::move(adapter));
		}
	}
}

void stream_registry::register_stream(::streams &stream) {
	for(auto proto : stream.dispatch_protocols()) {
		m_dispatcher.emplace(proto, &stream);
	}
}

::streams* stream_registry::dispatch_target(std::string_view proto) const {
	const auto it = m_dispatcher.find(proto);
	if(it == m_dispatcher.end()) {
		return nullptr;
	}
	return it->second;
}

int stream_registry::process_packet(tsv::ctx &tc, const tsv::row_t &row, const packet_context &packet) {
	std::vector<protocol_dispatch_decision> dispatch_decisions;
	dispatch_decisions.reserve(m_dispatch_adapters.size());
	bool adapter_observe_stream = false;
	bool adapter_suppress_other = false;
	for(auto &adapter : m_dispatch_adapters) {
		auto decision = adapter->prepare(packet);
		adapter_observe_stream = adapter_observe_stream || decision.observe_stream;
		adapter_suppress_other = adapter_suppress_other || decision.suppress_other;
		dispatch_decisions.emplace_back(std::move(decision));
	}

	bool dispatched_to_stream = false;
	const bool observe_stream =
		m_protocols.should_observe(packet.dispatch_proto, packet.src, packet.dst, packet.vlan, packet.host) ||
		adapter_observe_stream;
	if(observe_stream) {
		if(auto *target = dispatch_target(packet.dispatch_proto)) {
			target->process(tc, row);
			dispatched_to_stream = true;
		}
		else if(!adapter_suppress_other) {
			m_other->process(tc, row);
		}
	}

	for(std::size_t i = 0; i < m_dispatch_adapters.size(); ++i) {
		m_dispatch_adapters[i]->after_stream_dispatch(tc, row, packet, dispatch_decisions[i], dispatched_to_stream);
	}
	for(std::size_t i = 0; i < m_dispatch_adapters.size(); ++i) {
		m_dispatch_adapters[i]->after_packet(tc, row, packet, dispatch_decisions[i]);
	}

	return 0;
}

void stream_registry::update_events(double now) {
	for(auto &adapter : m_dispatch_adapters) {
		adapter->prune(now);
	}
	for(auto *stream : m_output_streams) {
		stream->update_events(now);
	}
}

void stream_registry::append_metrics(double now, json::array_t &out) {
	for(auto *stream : m_output_streams) {
		stream->append_metrics(now, out);
	}
}

void stream_registry::append_list(double now, json::array_t &out) {
	for(auto *stream : m_output_streams) {
		stream->append_list(now, out);
	}
}
#ifndef ALERT_EVALUATOR_H
#define ALERT_EVALUATOR_H

#include <filesystem>
#include <map>
#include <optional>
#include <string>
#include <vector>

#include "event.h"
#include "json.h"

class alert_evaluator {
public:
	enum class rule_type {
		threshold,
		counter_delta,
	};

	enum class compare_op {
		gt,
		ge,
		lt,
		le,
		eq,
		ne,
	};

	struct rule {
		std::string id;
		std::string target{"any"};
		std::string proto;
		std::string metric;
		rule_type type{rule_type::threshold};
		compare_op op{compare_op::gt};
		double error_threshold{0.0};
		double recover_threshold{0.0};
		double delta_threshold{0.0};
		double recover_after_sec{3.0};
		std::string severity{"warning"};
		bool enabled{true};
	};

	explicit alert_evaluator(event_sink &events);

	int load(const std::filesystem::path &path);
	bool empty() const noexcept { return m_rules.empty(); }
	void evaluate(double now, const json::array_t &metrics, const json::array_t &interfaces);
	json::array_t active_alerts() const;

private:
	struct state {
		bool active{false};
		bool has_last_value{false};
		double last_value{0.0};
		double last_error_time{0.0};
		double last_seen_time{0.0};
		json source{json::object()};
		json detail{json::object()};
	};

	event_sink &m_events;
	std::vector<rule> m_rules;
	std::map<std::string, state> m_states;

	void evaluate_entry(double now, const rule &r, const json &entry, bool is_interface);
	void evaluate_threshold(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, state &s, double value);
	void evaluate_counter_delta(double now, const rule &r, const json &entry, bool is_interface, const std::string &state_key, state &s, double value);
	void emit_alert(double now, const rule &r, const json &entry, bool is_interface, std::string action, double value, json detail);
	void update_active_state(double now, const rule &r, const json &entry, bool is_interface, state &s, double value, json detail);

	static std::optional<double> metric_value(const json &entry, const std::string &path);
	static bool compare(double lhs, compare_op op, double rhs);
	static bool matches_target(const rule &r, const json &entry, bool is_interface);
	static std::string make_state_key(const rule &r, const json &entry, bool is_interface);
	static json make_target_source(const rule &r, const json &entry, bool is_interface);
	static rule_type parse_rule_type(const std::string &value);
	static compare_op parse_compare_op(const std::string &value);
};

#endif /* ALERT_EVALUATOR_H */
#include "alert_evaluator.h"

#include <cmath>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <utility>

namespace {

std::vector<std::string> split_path(const std::string &path) {
	std::vector<std::string> out;
	std::size_t start = 0;
	while(start <= path.size()) {
		const auto pos = path.find('.', start);
		const auto end = (pos == std::string::npos) ? path.size() : pos;
		if(end > start) {
			out.emplace_back(path.substr(start, end - start));
		}
		if(pos == std::string::npos) {
			break;
		}
		start = pos + 1;
	}
	return out;
}

std::string json_string_or_empty(const json &j, const char *key) {
	if(!j.is_object() || !j.contains(key) || j[key].is_null()) {
		return {};
	}
	if(j[key].is_string()) {
		return j[key].get<std::string>();
	}
	if(j[key].is_number_integer()) {
		return std::to_string(j[key].get<long long>());
	}
	if(j[key].is_number_unsigned()) {
		return std::to_string(j[key].get<unsigned long long>());
	}
	if(j[key].is_number_float()) {
		return std::to_string(j[key].get<double>());
	}
	return {};
}

bool read_bool(const json &j, const char *key, bool fallback) {
	if(!j.contains(key) || !j[key].is_boolean()) {
		return fallback;
	}
	return j[key].get<bool>();
}

} // namespace

alert_evaluator::alert_evaluator(event_sink &events)
	: m_events(events) {
}

int alert_evaluator::load(const std::filesystem::path &path) {
	m_rules.clear();
	m_states.clear();

	if(path.empty()) {
		return 0;
	}

	std::ifstream in(path);
	if(!in) {
		std::cerr << "alert_evaluator: failed to open " << path << std::endl;
		return -1;
	}

	json root;
	try {
		in >> root;
	}
	catch(const std::exception &e) {
		std::cerr << "alert_evaluator: failed to parse " << path << ": " << e.what() << std::endl;
		return -1;
	}

	const json *rules_json = nullptr;
	if(root.is_object() && root.contains("alerts") && root["alerts"].is_array()) {
		rules_json = &root["alerts"];
	}
	else if(root.is_array()) {
		rules_json = &root;
	}
	else {
		std::cerr << "alert_evaluator: root.alerts must be an array" << std::endl;
		return -1;
	}

	for(const auto &entry : *rules_json) {
		try {
		if(!entry.is_object()) {
			std::cerr << "alert_evaluator: alert entry must be an object" << std::endl;
			return -1;
		}
		if(!entry.contains("id") || !entry["id"].is_string()) {
			std::cerr << "alert_evaluator: alert entry requires string id" << std::endl;
			return -1;
		}
		if(!entry.contains("metric") || !entry["metric"].is_string()) {
			std::cerr << "alert_evaluator: alert " << entry["id"] << " requires string metric" << std::endl;
			return -1;
		}

		rule r;
		r.id = entry["id"].get<std::string>();
		r.metric = entry["metric"].get<std::string>();
		if(entry.contains("target") && entry["target"].is_string()) r.target = entry["target"].get<std::string>();
		if(entry.contains("proto") && entry["proto"].is_string()) r.proto = entry["proto"].get<std::string>();
		if(entry.contains("type") && entry["type"].is_string()) r.type = parse_rule_type(entry["type"].get<std::string>());
		if(entry.contains("operator") && entry["operator"].is_string()) r.op = parse_compare_op(entry["operator"].get<std::string>());
		if(entry.contains("error_threshold")) r.error_threshold = entry["error_threshold"].get<double>();
		if(entry.contains("recover_threshold")) r.recover_threshold = entry["recover_threshold"].get<double>();
		else r.recover_threshold = r.error_threshold;
		if(entry.contains("delta_threshold")) r.delta_threshold = entry["delta_threshold"].get<double>();
		if(entry.contains("recover_after_sec")) r.recover_after_sec = entry["recover_after_sec"].get<double>();
		if(entry.contains("severity") && entry["severity"].is_string()) r.severity = entry["severity"].get<std::string>();
		r.enabled = read_bool(entry, "enabled", true);

		m_rules.push_back(std::move(r));
		}
		catch(const std::exception &e) {
			std::cerr << "alert_evaluator: invalid alert entry: " << e.what() << std::endl;
			return -1;
		}
	}

	return 0;
}

void alert_evaluator::evaluate(double now, const json::array_t &metrics, const json::array_t &interfaces) {
	for(const auto &entry : metrics) {
		if(!entry.is_object()) {
			continue;
		}
		for(const auto &r : m_rules) {
			if(!r.enabled) {
				continue;
			}
			evaluate_entry(now, r, entry, false);
		}
	}
	for(const auto &entry : interfaces) {
		if(!entry.is_object()) {
			continue;
		}
		for(const auto &r : m_rules) {
			if(!r.enabled) {
				continue;
			}
			evaluate_entry(now, r, entry, true);
		}
	}
}

json::array_t alert_evaluator::active_alerts() const {
	json::array_t out;
	for(const auto &[state_key, s] : m_states) {
		if(!s.active) {
			continue;
		}
		json entry = s.source.is_object() ? s.source : json::object();
		if(s.detail.is_object()) {
			for(const auto &[key, value] : s.detail.items()) {
				if(!entry.contains(key)) {
					entry[key] = value;
				}
			}
		}
		entry["state_key"] = state_key;
		entry["state"] = "active";
		entry["last_value"] = s.last_value;
		entry["last_error_time"] = s.last_error_time;
		entry["last_seen_time"] = s.last_seen_time;
		out.push_back(std::move(entry));
	}
	return out;
}

void alert_evaluator::evaluate_entry(double now, const rule &r, const json &entry, bool is_interface) {
	if(!matches_target(r, entry, is_interface)) {
		return;
	}
	auto value = metric_value(entry, r.metric);
	if(!value.has_value() || !std::isfinite(*value)) {
		return;
	}

	const auto state_key = make_state_key(r, entry, is_interface);
	auto &s = m_states[state_key];
	s.last_seen_time = now;

	switch(r.type) {
	case rule_type::threshold:
		evaluate_threshold(now, r, entry, is_interface, state_key, s, *value);
		break;
	case rule_type::counter_delta:
		evaluate_counter_delta(now, r, entry, is_interface, state_key, s, *value);
		break;
	}
}

void alert_evaluator::evaluate_threshold(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
	if(!s.active) {
		if(compare(value, r.op, r.error_threshold)) {
			s.active = true;
			s.last_error_time = now;
			json detail{
				{"metric", r.metric},
				{"value", value},
				{"threshold", r.error_threshold},
				{"operator", "error"},
			};
			update_active_state(now, r, entry, is_interface, s, value, detail);
			emit_alert(now, r, entry, is_interface, "detected", value, std::move(detail));
		}
		return;
	}

	if(!compare(value, r.op, r.recover_threshold)) {
		s.active = false;
		emit_alert(now, r, entry, is_interface, "recovered", value, json{
			{"metric", r.metric},
			{"value", value},
			{"threshold", r.recover_threshold},
			{"operator", "recover"},
		});
		return;
	}

	update_active_state(now, r, entry, is_interface, s, value, json{
		{"metric", r.metric},
		{"value", value},
		{"threshold", r.error_threshold},
		{"operator", "error"},
	});
}

void alert_evaluator::evaluate_counter_delta(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
	if(!s.has_last_value) {
		s.has_last_value = true;
		s.last_value = value;
		return;
	}

	const double delta = value - s.last_value;
	s.last_value = value;
	if(compare(delta, r.op, r.delta_threshold)) {
		json detail{
			{"metric", r.metric},
			{"value", value},
			{"delta", delta},
			{"threshold", r.delta_threshold},
		};
		if(!s.active) {
			s.active = true;
			emit_alert(now, r, entry, is_interface, "detected", value, detail);
		}
		s.last_error_time = now;
		update_active_state(now, r, entry, is_interface, s, value, std::move(detail));
		return;
	}

	if(s.active && (now - s.last_error_time) >= r.recover_after_sec) {
		s.active = false;
		emit_alert(now, r, entry, is_interface, "recovered", value, json{
			{"metric", r.metric},
			{"value", value},
			{"delta", delta},
			{"recover_after_sec", r.recover_after_sec},
		});
	}
}

void alert_evaluator::emit_alert(double now, const rule &r, const json &entry, bool is_interface, std::string action, double value, json detail) {
	detail["alert_id"] = r.id;
	detail["severity"] = r.severity;
	detail["action"] = action;
	detail["value"] = value;

	m_events.emit(event_record{
		.time_epoch = now,
		.type = action == "detected" ? "alert_detected" : "alert_recovered",
		.source = make_target_source(r, entry, is_interface),
		.detail = std::move(detail),
	});
}

void alert_evaluator::update_active_state(double now, const rule &r, const json &entry, bool is_interface, state &s, double value, json detail) {
	detail["alert_id"] = r.id;
	detail["severity"] = r.severity;
	detail["value"] = value;
	s.source = make_target_source(r, entry, is_interface);
	s.detail = std::move(detail);
	s.last_value = value;
	s.last_seen_time = now;
}

std::optional<double> alert_evaluator::metric_value(const json &entry, const std::string &path) {
	const json *cur = &entry;
	for(const auto &part : split_path(path)) {
		if(!cur->is_object() || !cur->contains(part)) {
			return std::nullopt;
		}
		cur = &(*cur)[part];
	}
	if(cur->is_number()) {
		return cur->get<double>();
	}
	return std::nullopt;
}

bool alert_evaluator::compare(double lhs, compare_op op, double rhs) {
	switch(op) {
	case compare_op::gt: return lhs > rhs;
	case compare_op::ge: return lhs >= rhs;
	case compare_op::lt: return lhs < rhs;
	case compare_op::le: return lhs <= rhs;
	case compare_op::eq: return lhs == rhs;
	case compare_op::ne: return lhs != rhs;
	}
	return false;
}

bool alert_evaluator::matches_target(const rule &r, const json &entry, bool is_interface) {
	if(r.target == "interface") {
		return is_interface;
	}
	if(is_interface) {
		return r.target == "any";
	}
	if(r.target == "flow" && !entry.contains("flow_key")) {
		return false;
	}
	if(r.target == "stream" && entry.contains("flow_key")) {
		return false;
	}
	if(!r.proto.empty()) {
		const auto proto = json_string_or_empty(entry, "proto");
		if(proto != r.proto) {
			return false;
		}
	}
	return true;
}

std::string alert_evaluator::make_state_key(const rule &r, const json &entry, bool is_interface) {
	std::ostringstream ss;
	ss << r.id;
	if(is_interface) {
		ss << "|interface=" << json_string_or_empty(entry, "interface_id")
		   << "|name=" << json_string_or_empty(entry, "name");
		return ss.str();
	}
	ss << "|proto=" << json_string_or_empty(entry, "proto")
	   << "|stream=" << json_string_or_empty(entry, "stream_key");
	const auto flow_key = json_string_or_empty(entry, "flow_key");
	if(!flow_key.empty()) {
		ss << "|flow=" << flow_key;
	}
	return ss.str();
}

json alert_evaluator::make_target_source(const rule &r, const json &entry, bool is_interface) {
	json source{
		{"alert_id", r.id},
		{"severity", r.severity},
		{"target", is_interface ? "interface" : (entry.contains("flow_key") ? "flow" : "stream")},
	};
	for(const auto &key : {"proto", "stream_key", "flow_key", "interface_id", "name"}) {
		if(entry.contains(key)) {
			source[key] = entry[key];
		}
	}
	return source;
}

alert_evaluator::rule_type alert_evaluator::parse_rule_type(const std::string &value) {
	if(value == "threshold") return rule_type::threshold;
	if(value == "counter_delta") return rule_type::counter_delta;
	throw std::runtime_error("unknown alert rule type: " + value);
}

alert_evaluator::compare_op alert_evaluator::parse_compare_op(const std::string &value) {
	if(value == ">") return compare_op::gt;
	if(value == ">=") return compare_op::ge;
	if(value == "<") return compare_op::lt;
	if(value == "<=") return compare_op::le;
	if(value == "==") return compare_op::eq;
	if(value == "!=") return compare_op::ne;
	throw std::runtime_error("unknown alert operator: " + value);
}

item.aggregated_output:
		}
	}

	port = value;
	return true;
}

bool protocol_map::parse_endpoint(const std::string &endpoint, ip_endpoint &out) {
	unsigned port = 0;
	if(!endpoint_port(endpoint, port)) {
		return false;
	}

	std::string host;
	if(!endpoint.empty() && endpoint.front() == '[') {
		const auto close = endpoint.find(']');
		if(close == std::string::npos || close + 1 >= endpoint.size() || endpoint[close + 1] != ':') {
			return false;
		}
		host = endpoint.substr(1, close - 1);
	}
	else {
		const auto pos = endpoint.rfind(':');
		if(pos == std::string::npos || endpoint.find(':') != pos) {
			return false;
		}
		host = endpoint.substr(0, pos);
	}

	ip_addr addr{};
	if(!parse_ip(host, addr)) {
		return false;
	}
	out = ip_endpoint{addr, static_cast<std::uint16_t>(port)};
	return true;
}

bool protocol_map::auto_decode_as(std::string_view proto, unsigned port, std::string &out) {
	const std::string p = upper(proto);
	if(p == "SRT") {
		out = "udp.port==" + std::to_string(port) + ",srt";
		return true;
	}
	if(p == "RTP") {
		out = "udp.port==" + std::to_string(port) + ",rtp";
		return true;
	}
	if(p == "RTMP") {
		out = "tcp.port==" + std::to_string(port) + ",rtmpt";
		return true;
	}
	if(p == "HTTP" || p == "HLS") {
		out = "tcp.port==" + std::to_string(port) + ",http";
		return true;
	}
	return false;
}

void protocol_map::add_decode_as(std::string value) {
	if(value.empty()) {
		return;
	}
	if(std::find(m_decode_as_rules.begin(), m_decode_as_rules.end(), value) != m_decode_as_rules.end()) {
		return;
	}
	m_decode_as_rules.push_back(std::move(value));
}


bool protocol_map::proto_matches(std::string_view rule_proto, std::string_view observed_proto) {
	const std::string rule = upper(rule_proto);
	const std::string observed = upper(observed_proto);
	if(rule == observed) {
		return true;
	}
	return (rule == "HLS" && observed == "HTTP") ||
	       (rule == "HTTP" && observed == "HLS") ||
	       ((rule == "HLS" || rule == "HTTP") && is_tls_proto(observed_proto)) ||
	       (rule == "RTMP" && observed == "RTMPT") ||
	       (rule == "RTMPT" && observed == "RTMP");
}

bool protocol_map::is_dedicated_proto(std::string_view proto) {
	const std::string p = upper(proto);
	return p == "RTP" || p == "SRT" || p == "HTTP" || p == "HLS" || p == "RTMP" || p == "RTMPT";
}

bool protocol_map::vlan_matches(const vlan_match &rule_vlan, const tsv::vlan_info &packet_vlan) {
	switch(rule_vlan.type) {
	case vlan_match::mode::any:
		return true;
	case vlan_match::mode::untagged:
		return packet_vlan.empty();
	case vlan_match::mode::id:
		return packet_vlan.id == rule_vlan.id;
	}
	return false;
}

bool protocol_map::endpoint_matches(const rule &r, const ip_endpoint &configured, const ip_endpoint &candidate) {
	if(configured.addr == candidate.addr && configured.port == candidate.port) {
		return true;
	}

	if(!(upper(r.proto) == "RTP" && r.fec)) {
		return false;
	}
	if(!(configured.addr == candidate.addr)) {
		return false;
	}
	if(candidate.port < configured.port) {
		return false;
	}

	const auto offset = static_cast<unsigned>(candidate.port - configured.port);
	return offset == 2U || offset == 4U;
}

bool protocol_map::endpoint_matches(const rule &r, const ip_endpoint &candidate) {
	for(const auto &endpoint : r.endpoints) {
		ip_endpoint configured{};
		if(!parse_endpoint(endpoint, configured)) {
			continue;
		}
		if(endpoint_matches(r, configured, candidate)) {
			return true;
		}
	}
	return false;
}

bool protocol_map::host_matches(const rule &r, std::string_view host) {
	if(host.empty()) {
		return false;
	}

	const auto observed = lower_host(host);
	if(observed.empty()) {
		return false;
	}

	for(const auto &configured_host : r.hosts) {
		const auto configured = lower_host(configured_host);
		if(configured.empty()) {
			continue;
		}
		if(configured == observed) {
			return true;
		}
		if(configured.size() > 2 && configured[0] == '*' && configured[1] == '.') {
			const auto suffix = configured.substr(1);
			if(observed.size() >= suffix.size() &&
			   observed.compare(observed.size() - suffix.size(), suffix.size(), suffix) == 0) {
				return true;
			}
		}
	}

	return false;
}

bool protocol_map::should_observe(std::string_view proto,
                                  const ip_endpoint &src,
                                  const ip_endpoint &dst,
                                  const tsv::vlan_info &vlan,
                                  std::string_view host) const {
	if(m_observe_mode == observe_mode::all) {
		return true;
	}
	if(m_observe_mode == observe_mode::configured_plus_other && !is_dedicated_proto(proto)) {
		return true;
	}

	for(const auto &r : m_rules) {
		if(!r.observe) {
			continue;
		}
		if(!proto_matches(r.proto, proto)) {
			continue;
		}
		if(!vlan_matches(r.vlan, vlan)) {
			continue;
		}
		if(endpoint_matches(r, src) || endpoint_matches(r, dst) || host_matches(r, host)) {
			return true;
		}
	}

	return false;
}


bool protocol_map::has_observable_host_rule(std::string_view proto, const tsv::vlan_info &vlan) const {
	for(const auto &r : m_rules) {
		if(!r.observe || r.hosts.empty()) {
			continue;
		}
		if(!proto_matches(r.proto, proto)) {
			continue;
		}
		if(!vlan_matches(r.vlan, vlan)) {
			continue;
		}
		return true;
	}
	return false;
}
#include "stream_registry.h"

#include <utility>

#include "event.h"

stream_registry::protocol_configs stream_registry::make_protocol_configs(const protocol_map &protocols) {
	protocol_configs cfg{};
	cfg.rtp.fec_base_endpoints = protocols.rtp_fec_base_endpoints();
	return cfg;
}

stream_registry::stream_registry(const protocol_map &protocols, event_sink &events)
	: m_protocols(protocols) {
	auto cfg = make_protocol_configs(protocols);

	m_srt = std::make_unique<srt::streams>(cfg.srt, events);
	m_rtp = std::make_unique<rtp::streams>(cfg.rtp, events);
	m_rtmp = std::make_unique<rtmp::streams>(cfg.rtmp, events);
	m_hls = std::make_unique<hls::streams>(cfg.hls, events);
	m_other = std::make_unique<other::streams>(cfg.other, events);

	m_all_streams = { m_srt.get(), m_rtp.get(), m_rtmp.get(), m_hls.get(), m_other.get() };
	// Preserve the existing monitor output order. RTMP dispatch exists, but metrics/list output was not emitted before this refactor.
	m_output_streams = { m_srt.get(), m_rtp.get(), m_hls.get(), m_other.get() };

	dispatch_adapter_context dispatch_ctx{
		.protocols = m_protocols,
		.other_fallback = *m_other,
	};
	for(auto *stream : m_all_streams) {
		register_stream(*stream);
		if(auto adapter = stream->make_dispatch_adapter(dispatch_ctx)) {
			m_dispatch_adapters.emplace_back(std::move(adapter));
		}
	}
}

void stream_registry::register_stream(::streams &stream) {
	for(auto proto : stream.dispatch_protocols()) {
		m_dispatcher.emplace(proto, &stream);
	}
}

::streams* stream_registry::dispatch_target(std::string_view proto) const {
	const auto it = m_dispatcher.find(proto);
	if(it == m_dispatcher.end()) {
		return nullptr;
	}
	return it->second;
}

int stream_registry::process_packet(tsv::ctx &tc, const tsv::row_t &row, const packet_context &packet) {
	std::vector<protocol_dispatch_decision> dispatch_decisions;
	dispatch_decisions.reserve(m_dispatch_adapters.size());
	bool adapter_observe_stream = false;
	bool adapter_suppress_other = false;
	for(auto &adapter : m_dispatch_adapters) {
		auto decision = adapter->prepare(packet);
		adapter_observe_stream = adapter_observe_stream || decision.observe_stream;
		adapter_suppress_other = adapter_suppress_other || decision.suppress_other;
		dispatch_decisions.emplace_back(std::move(decision));
	}

	bool dispatched_to_stream = false;
	const bool observe_stream =
		m_protocols.should_observe(packet.dispatch_proto, packet.src, packet.dst, packet.vlan, packet.host) ||
		adapter_observe_stream;
	if(observe_stream) {
		if(auto *target = dispatch_target(packet.dispatch_proto)) {
			target->process(tc, row);
			dispatched_to_stream = true;
		}
		else if(!adapter_suppress_other) {
			m_other->process(tc, row);
		}
	}

	for(std::size_t i = 0; i < m_dispatch_adapters.size(); ++i) {
		m_dispatch_adapters[i]->after_stream_dispatch(tc, row, packet, dispatch_decisions[i], dispatched_to_stream);
	}
	for(std::size_t i = 0; i < m_dispatch_adapters.size(); ++i) {
		m_dispatch_adapters[i]->after_packet(tc, row, packet, dispatch_decisions[i]);
	}

	return 0;
}

void stream_registry::update_events(double now) {
	for(auto &adapter : m_dispatch_adapters) {
		adapter->prune(now);
	}
	for(auto *stream : m_output_streams) {
		stream->update_events(now);
	}
}

void stream_registry::append_metrics(double now, json::array_t &out) {
	for(auto *stream : m_output_streams) {
		stream->append_metrics(now, out);
	}
}

void stream_registry::append_list(double now, json::array_t &out) {
	for(auto *stream : m_output_streams) {
		stream->append_list(now, out);
	}
}
