function newRule(tab: Exclude<Tab, "all">, rows: AlertRule[]): AlertRule {
  const prefix = tab === "general" ? "general" : tab.toLowerCase();
  const id = nextId(prefix + "_rule", rows);
  if (tab === "interface") return { id, enabled: true, target: "interface", metric: "rx.errors.window", type: "counter_delta", delta_threshold: 0, recover_after_sec: 3, severity: "warning" };
  if (tab === "HLS") return { id, enabled: false, target: "flow", proto: "HLS", metric: "hls.preview.http_5xx_count", type: "threshold", operator: ">", error_threshold: 0, recover_threshold: 0, severity: "warning" };
  if (tab === "RTP" || tab === "RTMP" || tab === "SRT") return { id, enabled: true, target: "flow", proto: tab, metric: "bitrate.bps", type: "threshold", operator: ">", error_threshold: 0, recover_threshold: 0, severity: "warning" };
  return { id, enabled: true, target: "flow", metric: "bitrate.bps", type: "threshold", operator: ">", error_threshold: 0, recover_threshold: 0, severity: "warning" };
}
function nextId(prefix: string, rows: AlertRule[]) { let number = 1; while (rows.some((row) => row.id === prefix + "_" + number)) number += 1; return prefix + "_" + number; }
function ruleTab(rule: AlertRule): Tab { if (rule.target === "interface") return "interface"; if (rule.proto === "RTP" || rule.proto === "RTMP" || rule.proto === "SRT" || rule.proto === "HLS") return rule.proto; return "general"; }
function numberOrUndefined(value: string) { return value === "" ? undefined : Number(value); }
function matchesMetric(metric: AlertMetricDefinition, query: string) { const normalized = query.trim().toLowerCase(); return !normalized || [metric.key, metric.description, metric.unit].some((value) => value?.toLowerCase().includes(normalized)); }
function supportsMetric(metric: AlertMetricDefinition, target: string, proto: string | undefined) {
  if (target === "interface") return metric.key !== "link.carrier" && (metric.key === "interval_sec" || metric.key.startsWith("link.") || metric.key.startsWith("rx.") || metric.key.startsWith("tx."));
  if (proto === "HLS") return metric.preview;
  if (proto === "RTP" || proto === "RTMP") return startsWithAny(metric.key, ["bitrate.", "packet_rate.", "packet_count.", "interval.", "jitter.", "clock_skew.", "seq_stats."]);
  if (proto === "SRT") return startsWithAny(metric.key, ["bitrate.", "packet_rate.", "packet_count.", "interval.", "jitter.", "packet_breakdown.", "control_type_count.", "seq_stats.", "rtt.", "rttvar.", "rate.", "rcvrate.", "bandwidth.", "nak_seqno."]);
  return startsWithAny(metric.key, ["bitrate.", "packet_rate.", "packet_count.", "duration."]);
}
function matchesRuleMetric(rule: AlertRule, metrics: AlertMetricDefinition[], query: string) {
  const metric = metrics.find((item) => item.key === rule.metric);
  return metric ? matchesMetric(metric, query) : !query.trim() || rule.metric.toLowerCase().includes(query.trim().toLowerCase());
}
function metricTooltip(metric: AlertMetricDefinition) { return [metric.key, metric.unit, metric.description].filter((value): value is string => Boolean(value)).join(" · "); }
function startsWithAny(value: string, prefixes: string[]) { return prefixes.some((prefix) => value.startsWith(prefix)); }

