int streams::process(tsv::ctx &c, const tsv::row_t &row) {
	info i;
	if(parse_row(c, row, i) != 0) {
		return 0;
	}

	int rc = 0;
	if(i.is_response || (!i.is_request && i.has_tcp_payload)) {
		const bool is_tcp_fallback = !i.is_response && i.has_tcp_payload;
		bool matched = false;
		const char *matched_by = "none";
		pending_request req{};
		const std::string conn_key = connection_key(i);
		if(i.has_tcp_payload) {
			m_last_payload_by_connection[conn_key] = i.time_epoch;
		}
		auto conn = m_pending_by_connection.find(conn_key);
		const std::size_t conn_pending = conn == m_pending_by_connection.end() ? 0U : conn->second.size();
		if(conn != m_pending_by_connection.end() && !conn->second.empty()) {
			const auto candidate = conn->second.front();
			if(is_tcp_fallback && !is_server_to_client_payload(candidate.fid, i)) {
				trace(4, "hls: tcp payload ignored direction role=%s path=%s src=%s dst=%s server_port=%u",
				      candidate.fid.role.c_str(),
				      candidate.fid.path.c_str(),
				      endpoint_key(i.src).c_str(),
				      endpoint_key(i.dst).c_str(),
				      static_cast<unsigned>(candidate.fid.port));
				rc |= flush_deferred(i.time_epoch);
				rc |= flush_pending_timeouts(i.time_epoch);
				return rc;
			}
			req = candidate;
			matched = true;
			matched_by = "connection";
		}
		else if(i.has_tcp_stream) {
			auto pending = m_pending_by_tcp_stream.find(i.tcp_stream);
			if(pending != m_pending_by_tcp_stream.end()) {
				const auto candidate = pending->second;
				if(is_tcp_fallback && !is_server_to_client_payload(candidate.fid, i)) {
					trace(4, "hls: tcp payload ignored direction role=%s path=%s src=%s dst=%s server_port=%u",
					      candidate.fid.role.c_str(),
					      candidate.fid.path.c_str(),
					      endpoint_key(i.src).c_str(),
					      endpoint_key(i.dst).c_str(),
					      static_cast<unsigned>(candidate.fid.port));
					rc |= flush_deferred(i.time_epoch);
					rc |= flush_pending_timeouts(i.time_epoch);
					return rc;
				}
				req = candidate;
				matched = true;
				matched_by = "tcp_stream";
			}
		}
		if(!matched) {
			if(is_tcp_fallback) {
				rc |= observe_connection_payload(conn_key, i);
			}
			trace(4, "hls: response unmatched status=%u tcp_payload=%d tcp_len=%u conn=%s conn_pending=%zu has_tcp_stream=%d tcp_stream=%u src=%s dst=%s",
			      static_cast<unsigned>(i.status_code),
			      i.has_tcp_payload ? 1 : 0,
			      static_cast<unsigned>(i.tcp_len),
			      conn_key.c_str(),
			      conn_pending,
			      i.has_tcp_stream ? 1 : 0,
			      static_cast<unsigned>(i.tcp_stream),
			      endpoint_key(i.src).c_str(),
			      endpoint_key(i.dst).c_str());
			rc |= flush_deferred(i.time_epoch);
			rc |= flush_pending_timeouts(i.time_epoch);
			return rc;
		}

		if(is_tcp_fallback) {
			auto deferred = m_deferred_by_connection.find(conn_key);
			if(deferred == m_deferred_by_connection.end()) {
				i.payload_seen = true;
				if(!i.has_content_length) {
					i.content_length = i.tcp_len;
					i.has_content_length = true;
				}
				m_deferred_by_connection.emplace(conn_key, deferred_response{req, i, conn_key});
				trace(3, "hls: tcp fallback deferred role=%s path=%s conn=%s grace=%.3f tcp_len=%u bytes=%llu",
				      req.fid.role.c_str(),
				      req.fid.path.c_str(),
				      conn_key.c_str(),
				      m_cfg.timeout.fallback_grace_sec,
				      static_cast<unsigned>(i.tcp_len),
				      static_cast<unsigned long long>(i.content_length));
			}
			else if(same_request(deferred->second.req, req)) {
				auto &response = deferred->second.response;
				const std::uint64_t payload_bytes = i.has_content_length ? i.content_length : i.tcp_len;
				response.payload_seen = true;
				response.has_tcp_payload = response.has_tcp_payload || i.has_tcp_payload;
				response.has_content_length = true;
				response.content_length += payload_bytes;
				response.tcp_len = i.tcp_len;
				response.time_epoch = i.time_epoch;
				trace(4, "hls: tcp fallback accumulated conn=%s tcp_len=%u total_bytes=%llu",
				      conn_key.c_str(),
				      static_cast<unsigned>(i.tcp_len),
				      static_cast<unsigned long long>(response.content_length));
			}
			else {
				trace(4, "hls: extra tcp fallback ignored for different request conn=%s tcp_len=%u",
				      conn_key.c_str(),
				      static_cast<unsigned>(i.tcp_len));
			}
			rc |= flush_deferred(i.time_epoch);
			rc |= flush_pending_timeouts(i.time_epoch);
			return rc;
		}

		auto deferred = m_deferred_by_connection.find(conn_key);
		if(deferred != m_deferred_by_connection.end() && same_request(deferred->second.req, req)) {
			const auto &fallback = deferred->second.response;
			if(fallback.payload_seen && fallback.content_length > i.content_length) {
				i.payload_seen = true;
				i.has_tcp_payload = i.has_tcp_payload || fallback.has_tcp_payload;
				i.has_content_length = true;
				i.content_length = fallback.content_length;
				trace(3, "hls: http status kept fallback bytes status=%u role=%s path=%s conn=%s bytes=%llu",
				      static_cast<unsigned>(i.status_code),
				      req.fid.role.c_str(),
				      req.fid.path.c_str(),
				      conn_key.c_str(),
				      static_cast<unsigned long long>(i.content_length));
			}
		}
		m_deferred_by_connection.erase(conn_key);
		pop_connection_pending(conn_key, req);
		erase_tcp_pending(req);
		rc |= process_response(std::move(i), req, matched_by, conn_pending, conn_key);
		rc |= flush_deferred(i.time_epoch);
		rc |= flush_pending_timeouts(i.time_epoch);
		return rc;
	}

	const auto hk = host_key(i.interface_id, i.host, i.port, i.vlan);
	const bool has_known_playlist = m_playlists_by_host.find(hk) != m_playlists_by_host.end();
	if(i.role == "other" && !has_known_playlist) {
		trace(4, "hls: ignore other request without playlist host=%s port=%u path=%s",
		      i.host.c_str(), static_cast<unsigned>(i.port), i.path.c_str());
		rc |= flush_deferred(i.time_epoch);
		rc |= flush_pending_timeouts(i.time_epoch);
		return rc;
	}
	const auto sid = resolve_stream_id(i);
	const auto fid = flow_id::from_request(i.interface_id, i.host, i.port, i.path, i.role, i.vlan);
	if(i.role == "playlist") {
		auto &playlists = m_playlists_by_host[hk];
		if(std::find(playlists.begin(), playlists.end(), i.path) == playlists.end()) {
			playlists.push_back(i.path);
			std::sort(playlists.begin(), playlists.end(), [](const auto &lhs, const auto &rhs) {
				return path_dir(lhs).size() > path_dir(rhs).size();
			});
		}
	}
	pending_request req{sid, fid, i.time_epoch};
	const std::string conn_key = connection_key(i);
	auto &queue = m_pending_by_connection[conn_key];
	queue.push_back(req);
	remember_connection_activity(conn_key, sid, fid);
	if(i.has_tcp_stream) {
		m_pending_by_tcp_stream[i.tcp_stream] = req;
	}
	trace(3, "hls: request registered method=%s role=%s path=%s conn=%s conn_pending=%zu has_tcp_stream=%d tcp_stream=%u stream=%s flow=%s",
	      i.method.c_str(),
	      i.role.c_str(),
	      i.path.c_str(),
	      conn_key.c_str(),
	      queue.size(),
	      i.has_tcp_stream ? 1 : 0,
	      static_cast<unsigned>(i.tcp_stream),
	      sid.to_stream_key().c_str(),
	      fid.to_flow_key(sid).c_str());

	rc |= process_resolved(sid, fid, i);
	rc |= flush_deferred(i.time_epoch);
	rc |= flush_pending_timeouts(i.time_epoch);
	return rc;
}

