lue="managed_target">Monitoring Target</option></select></td><td><input list={managed ? "monitoring-targets" : undefined} value={managed ? scope.target_id : scope.proto ?? ""} placeholder={managed ? "Target ID" : "Protocol"} disabled={busy} onChange={(event) => { const candidate = targets.find((item) => item.id === event.target.value); updateAssignment(index, { scope: managed ? { ...scope, target_id: event.target.value, target_type: candidate?.target_type ?? scope.target_type } : { ...scope, proto: event.target.value } }); }} />{managed && <datalist id="monitoring-targets">{targets.map((target) => <option key={target.id} value={target.id} label={target.target_type + " · " + target.proto + (target.title ? " · " + target.title : "")} />)}</datalist>}</td><td>{managed ? <select value={scope.target_type ?? "single"} disabled={busy} onChange={(event) => updateAssignment(index, { scope: { ...scope, target_type: event.target.value as "single" | "group" } })}><option value="single">Single</option><option value="group">Group</option></select> : <span>—</span>}</td><td><input value={profileCsv(assignment.profile_ids)} disabled={busy} onChange={(event) => updateAssignment(index, { profile_ids: parseIds(event.target.value) })} /></td><td><button type="button" className="maintenance-secondary-button icon-only" disabled={busy} onClick={() => onAssignments(assignments.filter((_, current) => current !== index))}><Icon name="delete" size={16} /></button></td></tr>; })}</tbody></table></div><button type="button" className="maintenance-secondary-button" disabled={busy} onClick={() => onAssignments([...assignments, { scope: { kind: "protocol", proto: "RTP", target: "flow" }, profile_ids: [] }])}>Add assignment</button><p className="maintenance-intro">Use the same stable ID as Monitoring targets. Single overrides group; group overrides the protocol default.</p></section>;
}
function nextProfileId(profiles: AlertProfile[]) { let n = 1; while (profiles.some((profile) => profile.id === "profile_" + n)) n += 1; return "profile_" + n; }

type AlertRowProps = { index: number; row: AlertRule; metrics: AlertMetricDefinition[]; busy: boolean; onUpdate: (index: number, patch: Partial<AlertRule>) => void; onRemove: (index: number) => void };
