import { useEffect, useMemo, useState, type FormEvent } from "react";
import { getAlertsSettings, saveAlertsSettings } from "../api/client";
import type { AlertAssignment, AlertMetricDefinition, AlertProfile, AlertRule, AlertsDocument, AlertsResponse, MonitoringTargetDefinition } from "../types/api";
import { Icon } from "./ui/Icon";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

type Tab = "all" | "general" | "interface" | "RTP" | "RTMP" | "SRT" | "HLS";
type PaneState = "loading" | "idle" | "saving" | "saved" | "error";
type AlertsPaneProps = { onSaved: (rules: AlertRule[]) => void };

const tabs: Array<{ key: Tab; label: string }> = [
  { key: "all", label: "All" },
  { key: "general", label: "General" },
  { key: "interface", label: "Interface" },
  { key: "RTP", label: "RTP" },
  { key: "RTMP", label: "RTMP" },
  { key: "SRT", label: "SRT" },
  { key: "HLS", label: "HLS" }
];
const operators = [">", ">=", "<", "<=", "==", "!="] as const;
const severities = ["info", "warning", "error", "critical"];

export function AlertsPane({ onSaved }: AlertsPaneProps) {
  const [settings, setSettings] = useState<AlertsResponse | null>(null);
  const [rows, setRows] = useState<AlertRule[]>([]);
  const [profiles, setProfiles] = useState<AlertProfile[]>([]);
  const [assignments, setAssignments] = useState<AlertAssignment[]>([]);
  const [profileFormat, setProfileFormat] = useState(false);
  const [tab, setTab] = useState<Tab>("all");
  const [metricQuery, setMetricQuery] = useState("");
  const [state, setState] = useState<PaneState>("loading");
  const [message, setMessage] = useState("");

  const load = () => {
    setState("loading");
    void getAlertsSettings().then((next) => {
      setSettings(next);
      setRows(next.document.alerts ?? next.document.rules ?? []);
      setProfiles(next.document.profiles ?? []);
      setAssignments(next.document.assignments ?? []);
      setProfileFormat(Boolean(next.document.rules));
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load alerts settings");
    });
  };
  useEffect(load, []);

  const visibleRows = useMemo(() => rows.map((row, index) => ({ row, index })).filter(({ row }) => (tab === "all" || ruleTab(row) === tab) && matchesRuleMetric(row, settings?.metrics ?? [], metricQuery)), [rows, settings, tab, metricQuery]);
  const updateRow = (index: number, patch: Partial<AlertRule>) => setRows((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, ...patch } : row));
  const removeRow = (index: number) => setRows((current) => current.filter((_, rowIndex) => rowIndex !== index));
  const addRow = () => { if (tab !== "all") setRows((current) => [...current, newRule(tab, current)]); };

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings) return;
    setState("saving");
    setMessage("");
    const document: AlertsDocument = profileFormat ? { ...(settings.document._note ? { _note: settings.document._note } : {}), rules: rows, profiles, assignments } : { ...(settings.document._note ? { _note: settings.document._note } : {}), alerts: rows };
    void saveAlertsSettings(settings.revision, document).then((next) => {
      setSettings(next);
      setRows(next.document.alerts ?? next.document.rules ?? []);
      setProfiles(next.document.profiles ?? []);
      setAssignments(next.document.assignments ?? []);
      setProfileFormat(Boolean(next.document.rules));
      onSaved(next.document.alerts ?? next.document.rules ?? []);
      setState("saved");
      setMessage("Saved. Restart STM to apply the new alert rules.");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to apply alerts settings");
    });
  };

  return <PaneFrame className="maintenance-frame alerts-frame" header={<PaneHeader title="Alert rules" icon="alertRules" meta="STM thresholds and counter changes" actions={<button type="button" className="maintenance-secondary-button button-with-icon" onClick={load} disabled={state === "loading" || state === "saving"}><Icon name="reload" size={16} />Reload</button>} />}>
    <form className="maintenance-form" onSubmit={submit}>
      <div className="maintenance-intro">Rules are grouped by protocol. Metric candidates are filtered by the selected target and protocol; Apply writes <code>{settings?.path ?? "the configured alerts file"}</code>. Restart STM before the changes take effect.</div>
      <section className="maintenance-section alerts-toolbar">
        <div className="alerts-tabs" role="tablist" aria-label="Alert rule protocol">
          {tabs.map((item) => <button key={item.key} type="button" role="tab" aria-selected={tab === item.key} className={"alerts-tab" + (tab === item.key ? " is-active" : "")} onClick={() => setTab(item.key)}>{item.label}<span>{item.key === "all" ? rows.length : rows.filter((row) => ruleTab(row) === item.key).length}</span></button>)}
        </div>
        <label className="alerts-metric-search">Find metrics<input type="search" value={metricQuery} onChange={(event) => setMetricQuery(event.target.value)} placeholder="bitrate, rtt, packet…" /></label>
      </section>
      {!profileFormat && <section className="maintenance-section"><button type="button" className="maintenance-secondary-button" disabled={state === "saving"} onClick={() => { setProfileFormat(true); setProfiles([{ id: "default", title: "Default", rule_ids: [] }]); setAssignments([]); }}>Use profiles and assignments</button></section>}
      {tab === "HLS" && <div className="protocol-map-notice">HLS candidates are preview-only. They are shown to confirm the future UI and are not emitted or evaluated by STM yet.</div>}
      <section className="maintenance-section"><div className="maintenance-table-wrap"><table className="maintenance-table alerts-table"><colgroup><col className="alerts-col-index" /><col className="alerts-col-enabled" /><col className="alerts-col-id" /><col className="alerts-col-target" /><col className="alerts-col-metric" /><col className="alerts-col-rule" /><col className="alerts-col-trigger" /><col className="alerts-col-recovery" /><col className="alerts-col-severity" /><col className="alerts-col-delete" /></colgroup><thead><tr><th>#</th><th>Enabled</th><th>Rule ID</th><th>Target</th><th>Metric</th><th>Rule</th><th>Trigger</th><th>Recovery</th><th>Severity</th><th /></tr></thead><tbody>
        {visibleRows.map(({ row, index }) => <AlertRow key={index} index={index} row={row} metrics={settings?.metrics ?? []} busy={state === "saving"} onUpdate={updateRow} onRemove={removeRow} />)}
        {visibleRows.length === 0 && <tr><td colSpan={10} className="alerts-empty">{metricQuery.trim() ? "No matching alert rules in this tab." : <>No {tab === "all" ? "alert" : tab} rules.{tab === "all" ? " Choose a protocol tab to add one." : " Add a rule to begin."}</>}</td></tr>}
      </tbody></table></div><div className="protocol-map-row-actions">{tab !== "all" && <button type="button" className="maintenance-secondary-button button-with-icon" disabled={!settings || state === "saving"} onClick={addRow}><Icon name="add" size={16} />Add {tab === "general" ? "general" : tab} rule</button>}</div>{profileFormat && <ProfileAssignmentsEditor profiles={profiles} assignments={assignments} targets={settings?.monitoringTargets ?? []} rules={rows} busy={state === "saving"} onProfiles={setProfiles} onAssignments={setAssignments} />}
      </section>
      <footer className="maintenance-actions"><span className={"maintenance-message maintenance-message-" + state} role="status">{state === "loading" ? "Loading alert rules…" : message}</span><button type="submit" className="maintenance-save-button button-with-icon" disabled={!settings || state === "loading" || state === "saving"}><Icon name="save" size={16} />{state === "saving" ? "Applying…" : "Apply"}</button></footer>
    </form>
  </PaneFrame>;
}

type IdOption = { id: string; label: string };
type IdMultiSelectProps = { value: string[]; options: IdOption[]; busy: boolean; label: string; onChange: (value: string[]) => void };
function IdMultiSelect({ value, options, busy, label, onChange }: IdMultiSelectProps) {
  const known = new Map(options.map((option) => [option.id, option.label]));
  const add = (id: string) => { if (id && !value.includes(id)) onChange([...value, id]); };
  return <div className="alerts-id-picker">{value.map((id) => <span className={"alerts-id-chip" + (known.has(id) ? "" : " is-orphan")} key={id}>{known.get(id) ?? id + " (undefined)"}<button type="button" disabled={busy} onClick={() => onChange(value.filter((current) => current !== id))} aria-label={"Remove " + id}>×</button></span>)}<select value="" disabled={busy} aria-label={label} onChange={(event) => { add(event.target.value); event.currentTarget.value = ""; }}><option value="">+ Select</option>{options.filter((option) => !value.includes(option.id)).map((option) => <option key={option.id} value={option.id}>{option.label}</option>)}</select></div>;
}

type TargetPickerProps = { value: string; targetType: "single" | "group"; targets: MonitoringTargetDefinition[]; busy: boolean; onChange: (id: string, targetType: "single" | "group") => void };
function TargetPicker({ value, targetType, targets, busy, onChange }: TargetPickerProps) {
  const selected = targets.find((target) => target.id === value);
  const label = (target: MonitoringTargetDefinition) => target.id + " · " + target.target_type + " · " + target.proto + (target.title ? " · " + target.title : "");
  return <div className="alerts-target-picker"><select value={selected?.id ?? ""} disabled={busy} aria-label="Select Monitoring Target" onChange={(event) => { const target = targets.find((item) => item.id === event.target.value); if (target) onChange(target.id, target.target_type); }}><option value="">Select target</option>{targets.map((target) => <option key={target.id} value={target.id}>{label(target)}</option>)}</select><input value={value} disabled={busy} onChange={(event) => { const target = targets.find((item) => item.id === event.target.value); onChange(event.target.value, target?.target_type ?? targetType); }} placeholder="Or enter orphan ID" aria-label="Monitoring Target ID" /></div>;
}

type ProfileAssignmentsEditorProps = { profiles: AlertProfile[]; assignments: AlertAssignment[]; targets: MonitoringTargetDefinition[]; rules: AlertRule[]; busy: boolean; onProfiles: (profiles: AlertProfile[]) => void; onAssignments: (assignments: AlertAssignment[]) => void };
function ProfileAssignmentsEditor({ profiles, assignments, targets, rules, busy, onProfiles, onAssignments }: ProfileAssignmentsEditorProps) {
  const ruleOptions = rules.map((rule) => ({ id: rule.id, label: rule.id + (rule.proto ? " · " + rule.proto : "") + " · " + rule.metric }));
  const profileOptions = profiles.map((profile) => ({ id: profile.id, label: profile.id + (profile.title ? " · " + profile.title : "") }));
  const updateProfile = (index: number, patch: Partial<AlertProfile>) => onProfiles(profiles.map((profile, current) => current === index ? { ...profile, ...patch } : profile));
  const updateAssignment = (index: number, patch: Partial<AlertAssignment>) => onAssignments(assignments.map((assignment, current) => current === index ? { ...assignment, ...patch } as AlertAssignment : assignment));
  return <section className="maintenance-section alerts-profile-editor"><h3>Profiles and assignments</h3><p>Rules are reusable. Assign a profile to a protocol default, a group target, or a single Monitoring Target ID.</p><div className="maintenance-table-wrap"><table className="maintenance-table"><thead><tr><th>Profile ID</th><th>Title</th><th>Rule IDs</th><th /></tr></thead><tbody>{profiles.map((profile, index) => <tr key={index}><td><input value={profile.id} disabled={busy} onChange={(event) => updateProfile(index, { id: event.target.value })} /></td><td><input value={profile.title ?? ""} disabled={busy} onChange={(event) => updateProfile(index, { title: event.target.value })} /></td><td><IdMultiSelect value={profile.rule_ids} options={ruleOptions} busy={busy} label={"Rule IDs for " + profile.id} onChange={(rule_ids) => updateProfile(index, { rule_ids })} /></td><td><button type="button" className="maintenance-secondary-button icon-only" disabled={busy} onClick={() => onProfiles(profiles.filter((_, current) => current !== index))}><Icon name="delete" size={16} /></button></td></tr>)}</tbody></table></div><button type="button" className="maintenance-secondary-button" disabled={busy} onClick={() => onProfiles([...profiles, { id: nextProfileId(profiles), title: "", rule_ids: [] }])}>Add profile</button><div className="maintenance-table-wrap"><table className="maintenance-table"><thead><tr><th>Scope</th><th>Protocol / Target ID</th><th>Target type</th><th>Profile IDs</th><th /></tr></thead><tbody>{assignments.map((assignment, index) => { const scope = assignment.scope; const managed = scope.kind === "managed_target"; return <tr key={index}><td><select value={scope.kind} disabled={busy} onChange={(event) => updateAssignment(index, { scope: event.target.value === "managed_target" ? { kind: "managed_target", target_id: "", target_type: "single" } : { kind: "protocol", proto: "RTP", target: "flow" } })}><option value="protocol">Protocol default</option><option value="managed_target">Monitoring Target</option></select></td><td>{managed ? <TargetPicker value={scope.target_id} targetType={scope.target_type ?? "single"} targets={targets} busy={busy} onChange={(target_id, target_type) => updateAssignment(index, { scope: { ...scope, target_id, target_type } })} /> : <select value={scope.proto ?? ""} disabled={busy} onChange={(event) => updateAssignment(index, { scope: { ...scope, proto: event.target.value } })}><option value="">All protocols</option><option value="RTP">RTP</option><option value="SRT">SRT</option><option value="RTMP">RTMP</option><option value="HLS">HLS</option></select>}</td><td>{managed ? <select value={scope.target_type ?? "single"} disabled={busy} onChange={(event) => updateAssignment(index, { scope: { ...scope, target_type: event.target.value as "single" | "group" } })}><option value="single">Single</option><option value="group">Group</option></select> : <span>—</span>}</td><td><IdMultiSelect value={assignment.profile_ids} options={profileOptions} busy={busy} label="Profile IDs" onChange={(profile_ids) => updateAssignment(index, { profile_ids })} /></td><td><button type="button" className="maintenance-secondary-button icon-only" disabled={busy} onClick={() => onAssignments(assignments.filter((_, current) => current !== index))}><Icon name="delete" size={16} /></button></td></tr>; })}</tbody></table></div><button type="button" className="maintenance-secondary-button" disabled={busy} onClick={() => onAssignments([...assignments, { scope: { kind: "protocol", proto: "RTP", target: "flow" }, profile_ids: [] }])}>Add assignment</button><p className="maintenance-intro">Use the same stable ID as Monitoring targets. Single overrides group; group overrides the protocol default.</p></section>;
}
function nextProfileId(profiles: AlertProfile[]) { let n = 1; while (profiles.some((profile) => profile.id === "profile_" + n)) n += 1; return "profile_" + n; }

type AlertRowProps = { index: number; row: AlertRule; metrics: AlertMetricDefinition[]; busy: boolean; onUpdate: (index: number, patch: Partial<AlertRule>) => void; onRemove: (index: number) => void };
function AlertRow({ index, row, metrics, busy, onUpdate, onRemove }: AlertRowProps) {
  const target = row.target ?? "any";
  const type = row.type ?? "threshold";
  const candidates = metrics.filter((metric) => supportsMetric(metric, target, row.proto));
  const selected = metrics.find((metric) => metric.key === row.metric);
  const listId = "alert-metrics-" + index;
  const changeType = (nextType: AlertRule["type"]) => {
    if (nextType === "counter_delta") onUpdate(index, { type: nextType, delta_threshold: row.delta_threshold ?? 0, recover_after_sec: row.recover_after_sec ?? 3, error_threshold: undefined, recover_threshold: undefined });
    else onUpdate(index, { type: "threshold", operator: row.operator ?? ">", error_threshold: row.error_threshold ?? 0, recover_threshold: row.recover_threshold ?? 0, delta_threshold: undefined, recover_after_sec: undefined });
  };
  return <tr><td>{index + 1}</td><td><button type="button" role="switch" aria-checked={row.enabled !== false} className={"maintenance-switch " + (row.enabled !== false ? "is-on" : "is-off")} disabled={busy} onClick={() => onUpdate(index, { enabled: row.enabled === false })}>{row.enabled === false ? "Off" : "On"}</button></td><td><input className="alerts-id-input" value={row.id} disabled={busy} onChange={(event) => onUpdate(index, { id: event.target.value })} /></td><td><select value={target} disabled={busy || row.proto === "RTP" || row.proto === "RTMP" || row.proto === "SRT"} onChange={(event) => onUpdate(index, { target: event.target.value as AlertRule["target"], metric: "" })}><option value="flow">Flow</option><option value="stream">Stream</option><option value="interface">Interface</option><option value="any">Any</option></select></td><td><input className="alerts-metric-input" list={listId} value={row.metric} disabled={busy} onChange={(event) => onUpdate(index, { metric: event.target.value })} placeholder="Search metric" title={selected?.description ? metricTooltip(selected) : undefined} aria-label={selected?.description ? "Metric: " + metricTooltip(selected) : "Metric"} /><datalist id={listId}>{candidates.map((metric) => <option key={metric.key} value={metric.key} label={metric.description ?? metric.key} />)}</datalist>{selected?.preview && <span className="alerts-preview">Preview</span>}</td><td><span className="alerts-rule-controls"><select value={type} disabled={busy} onChange={(event) => changeType(event.target.value as AlertRule["type"])}><option value="threshold">Threshold</option><option value="counter_delta">Counter delta</option></select>{type === "threshold" && <select className="alerts-operator" value={row.operator ?? ">"} disabled={busy} onChange={(event) => onUpdate(index, { operator: event.target.value as AlertRule["operator"] })}>{operators.map((operator) => <option key={operator} value={operator}>{operator}</option>)}</select>}</span></td><td><input type="number" value={String(type === "counter_delta" ? row.delta_threshold ?? "" : row.error_threshold ?? "")} disabled={busy} onChange={(event) => onUpdate(index, type === "counter_delta" ? { delta_threshold: numberOrUndefined(event.target.value) } : { error_threshold: numberOrUndefined(event.target.value) })} /></td><td>{type === "counter_delta" ? <label className="alerts-inline-field">after<input type="number" min="0" value={String(row.recover_after_sec ?? "")} disabled={busy} onChange={(event) => onUpdate(index, { recover_after_sec: numberOrUndefined(event.target.value) })} /><span>s</span></label> : <input type="number" value={String(row.recover_threshold ?? "")} disabled={busy} onChange={(event) => onUpdate(index, { recover_threshold: numberOrUndefined(event.target.value) })} />}</td><td><select value={row.severity ?? "warning"} disabled={busy} onChange={(event) => onUpdate(index, { severity: event.target.value })}>{severities.map((severity) => <option key={severity} value={severity}>{severity}</option>)}</select></td><td><button type="button" className="maintenance-secondary-button icon-only" disabled={busy} onClick={() => onRemove(index)} aria-label="Delete alert rule" title="Delete alert rule"><Icon name="delete" size={16} /></button></td></tr>;
}

function newRule(tab: Exclude<Tab, "all">, rows: AlertRule[]): AlertRule {
  const prefix = tab === "general" ? "general" : tab.toLowerCase();
  const id = nextId(prefix + "_rule", rows);
  if (tab === "interface") return { id, enabled: true, target: "interface", metric: "rx.errors.window", type: "counter_delta", delta_threshold: 0, recover_after_sec: 3, severity: "warning" };
  if (tab === "HLS") return { id, enabled: false, target: "flow", proto: "HLS", metric: "hls.preview.http_5xx_count", type: "threshold", operator: ">", error_threshold: 0, recover_threshold: 0, severity: "warning" };
  if (tab === "RTP" || tab === "RTMP" || tab === "SRT") return { id, enabled: true, target: "flow", proto: tab, metric: "bitrate.bps", type: "threshold", operator: ">", error_threshold: 0, recover_threshold: 0, severity: "warning" };
  return { id, enabled: true, target: "flow", metric: "bitrate.bps", type: "threshold", operator: ">", error_threshold: 0, recover_threshold: 0, severity: "warning" };
}
function nextId(prefix: string, rows: AlertRule[]) { let number = 1; while (rows.some((row) => row.id === prefix + "_" + number)) number += 1; return prefix + "_" + number; }
function ruleTab(rule: AlertRule): Tab { if (rule.target === "interface") return "interface"; if (rule.proto === "RTP" || rule.proto === "RTMP" || rule.proto === "SRT" || rule.proto === "HLS") return rule.proto; return "general"; }
function numberOrUndefined(value: string) { return value === "" ? undefined : Number(value); }
function matchesMetric(metric: AlertMetricDefinition, query: string) { const normalized = query.trim().toLowerCase(); return !normalized || [metric.key, metric.description, metric.unit].some((value) => value?.toLowerCase().includes(normalized)); }
function supportsMetric(metric: AlertMetricDefinition, target: string, proto: string | undefined) {
  if (target === "interface") return metric.key !== "link.carrier" && (metric.key === "interval_sec" || metric.key.startsWith("link.") || metric.key.startsWith("rx.") || metric.key.startsWith("tx."));
  if (proto === "HLS") return metric.preview;
  if (proto === "RTP" || proto === "RTMP") return startsWithAny(metric.key, ["bitrate.", "packet_rate.", "packet_count.", "interval.", "jitter.", "clock_skew.", "seq_stats."]);
  if (proto === "SRT") return startsWithAny(metric.key, ["bitrate.", "packet_rate.", "packet_count.", "interval.", "jitter.", "packet_breakdown.", "control_type_count.", "seq_stats.", "rtt.", "rttvar.", "rate.", "rcvrate.", "bandwidth.", "nak_seqno."]);
  return startsWithAny(metric.key, ["bitrate.", "packet_rate.", "packet_count.", "duration."]);
}
function matchesRuleMetric(rule: AlertRule, metrics: AlertMetricDefinition[], query: string) {
  const metric = metrics.find((item) => item.key === rule.metric);
  return metric ? matchesMetric(metric, query) : !query.trim() || rule.metric.toLowerCase().includes(query.trim().toLowerCase());
}
function metricTooltip(metric: AlertMetricDefinition) { return [metric.key, metric.unit, metric.description].filter((value): value is string => Boolean(value)).join(" · "); }
function startsWithAny(value: string, prefixes: string[]) { return prefixes.some((prefix) => value.startsWith(prefix)); }
