const r = await tools.exec_command({"cmd":"rg -n 'ProfilesPane|ProfileDetail|ruleCondition|RuleCondition|AlertNumberInput|function newRule' fe/client/src/components/AlertsPane.tsx && tee -a fe/client/src/components/AlertsPane.tsx <<'EOF'

function rawValue(value: number, unit?: string) { return String(value) + (unit ? " " + unit : ""); }
function formatMetricValue(value: number | undefined, unit?: string) {
  if (value === undefined) return "—";
  if (unit === "s" && value !== 0 && Math.abs(value) < 1) return formatDisplayNumber(value * 1000) + " ms";
  if (supportsEngineeringUnit(unit)) { const part = engineeringPart(value); return formatDisplayNumber(part.value) + " " + part.prefix + displayBaseUnit(unit); }
