      dragConfig={{ enabled: editing, handle: ".inspector-drag-handle", cancel: ".inspector-cell-body, .inspector-cell-actions, input, select, .inspector-cell-remove, a" }}
      resizeConfig={{ enabled: editing, handles: ["se"] }} compactor={compactor(editMode)} autoSize onBreakpointChange={(value) => setActiveBreakpoint(toBreakpoint(value))} onLayoutChange={onLayoutChange}>
      {activeCells.map((cell) => <section key={cell.id} className={"dashboard-cell inspector-cell inspector-cell-" + cell.type}>
