function paramsForCellType(params: InspectorCell["params"], type: InspectorCellType, targetKind: InspectorTargetKind) { const next = { ...(params ?? {}) }; if (type !== "metric-chart") delete next.metricKey; else if (typeof next.metricKey !== "string") next.metricKey = targetKind === "interface" ? "rx.bitrate" : targetKind === "stream" ? "stream-bitrate" : "bitrate"; return Object.keys(next).length > 0 ? next : undefined; }
function compactor(editMode: number): Compactor { if (editMode === 1) return verticalCompactor; if (editMode === 2) return horizontalCompactor; return editMode === 3 ? pushCompactor : fixedCompactor; }
function breakpointForWidth(width: number): Breakpoint { return width >= BREAKPOINTS.desktop ? "desktop" : width >= BREAKPOINTS.tablet ? "tablet" : "mobile"; }
function toBreakpoint(value: string): Breakpoint { return value === "mobile" || value === "tablet" || value === "desktop" ? value : "desktop"; }
function toLayoutItem(cell: InspectorCell): LayoutItem { const minimum = cell.type === "metric-chart" || cell.type === "stream-bitrate" ? { minW: 4, minH: 5 } : cell.type === "all-flow-chart-group" ? { minW: 6, minH: 6 } : { minW: 2, minH: 3 }; return { i: cell.id, x: cell.grid.x, y: cell.grid.y, w: cell.grid.w, h: cell.grid.h, ...minimum, maxW: 48 }; }
function responsiveCells(cells: InspectorCell[], saved: InspectorResponsiveLayouts | undefined): Record<Breakpoint, InspectorCell[]> { return { desktop: saved?.desktop ?? cells, tablet: saved?.tablet ?? fallback(cells, 12, 2), mobile: saved?.mobile ?? fallback(cells, 4, 1) }; }
function fallback(cells: InspectorCell[], columns: number, count: number) { const width = Math.floor(columns / count); const result: InspectorCell[] = []; let y = 0; for (let index = 0; index < cells.length; index += count) { const row = cells.slice(index, index + count); const height = Math.max(...row.map((cell) => cell.grid.h), 3); row.forEach((cell, column) => result.push({ ...cell, grid: { x: column * width, y, w: width, h: cell.grid.h } })); y += height; } return result; }
function merge(cells: InspectorCell[], layout: Layout) { const positions = new Map(layout.map((item) => [item.i, item])); return cells.map((cell) => { const item = positions.get(cell.id); return item ? { ...cell, grid: { x: item.x, y: item.y, w: item.w, h: item.h } } : cell; }); }
