}

function ProtocolDetails({ details }: { details?: ProtocolDetail[] }) {
  if (!details || details.length === 0) return null;
  const tooltip = details.map((detail) => detail.label ? detail.label + " " + detail.value : detail.value).join(" · ");
  return <span className="stream-protocol-details" title={tooltip}>
