class expirable {
public:
    expirable() = default;
    virtual ~expirable() = default;

    void touch(double now) noexcept {
        m_last_seen = now;
        m_seen = true;
    }

    double last_seen() const noexcept {
        return m_last_seen;
    }

    bool seen() const noexcept {
        return m_seen;
    }

    bool expired(double now, double timeout_sec) const noexcept {
        return m_seen && (now - m_last_seen) >= timeout_sec;
    }

private:
    double m_last_seen = 0.0;
    bool   m_seen = false;
};

class streams {
public:
	virtual ~streams() = default;

	virtual int process(tsv::ctx &c, const tsv::row_t &row) = 0;
	// The registry supplies IDs of matching enabled Monitoring Targets.
	virtual int process(tsv::ctx &c, const tsv::row_t &row, const std::vector<std::string> &) { return process(c, row); }
	virtual int append_list(double now, json::array_t &out) = 0;
	virtual int update_events(double now) = 0;
	virtual int append_metrics(double now, json::array_t &out) = 0;
	virtual std::vector<std::string_view> dispatch_protocols() const {
		return {};
	}
	virtual std::unique_ptr<protocol_dispatch_adapter> make_dispatch_adapter(const dispatch_adapter_context&) {
		return nullptr;
	}
};

inline void merge_monitoring_target_ids(std::vector<std::string> &into, const std::vector<std::string> &ids) {
	for(const auto &id : ids) {
		if(!id.empty() && std::find(into.begin(), into.end(), id) == into.end()) into.push_back(id);
	}
}

inline void append_monitoring_target_ids(json::array_t &out, std::size_t first, const std::vector<std::string> &ids) {
	if(ids.empty()) return;
	for(std::size_t i = first; i < out.size(); ++i) out[i]["monitoring_target_ids"] = ids;
}

