#ifndef STREAMS_H
#define STREAMS_H

#include <algorithm>
#include <memory>
#include <string_view>
#include <vector>

#include "json.h"
#include "protocol_dispatch_adapter.h"
#include "tsv.h"

class expirable {
public:
    expirable() = default;
    virtual ~expirable() = default;

    void touch(double now) noexcept {
        m_last_seen = now;
        m_seen = true;
    }

    double last_seen() const noexcept {
        return m_last_seen;
    }

    bool seen() const noexcept {
        return m_seen;
    }

    bool expired(double now, double timeout_sec) const noexcept {
        return m_seen && (now - m_last_seen) >= timeout_sec;
    }

private:
    double m_last_seen = 0.0;
    bool   m_seen = false;
};

class streams {
public:
	virtual ~streams() = default;

	virtual int process(tsv::ctx &c, const tsv::row_t &row) = 0;
	// The registry supplies IDs of matching enabled Monitoring Targets.
	virtual int process(tsv::ctx &c, const tsv::row_t &row, const std::vector<std::string> &) { return process(c, row); }
	virtual int append_list(double now, json::array_t &out) = 0;
	virtual int update_events(double now) = 0;
	virtual int append_metrics(double now, json::array_t &out) = 0;
	virtual std::vector<std::string_view> dispatch_protocols() const {
		return {};
	}
	virtual std::unique_ptr<protocol_dispatch_adapter> make_dispatch_adapter(const dispatch_adapter_context&) {
		return nullptr;
	}
};

inline void merge_monitoring_target_ids(std::vector<std::string> &into, const std::vector<std::string> &ids) {
	for(const auto &id : ids) {
		if(!id.empty() && std::find(into.begin(), into.end(), id) == into.end()) into.push_back(id);
	}
}

inline void append_monitoring_target_ids(json::array_t &out, std::size_t first, const std::vector<std::string> &ids) {
	if(ids.empty()) return;
	for(std::size_t i = first; i < out.size(); ++i) out[i]["monitoring_target_ids"] = ids;
}

#endif /* STREAMS_H */
#include "stream_rtp.h"

#include <array>
#include <iostream>
#include <utility>

#include "json.h"
#include "trace.h"
#include "stream_json.h"
#include "tsv_util.h"

namespace rtp {

flow::flow(const stream_id& sid, const flow_id fid, std::string interface_name, event_sink &events)
	: m_fid(std::move(fid))
	, m_interface_name(std::move(interface_name))
	, m_events(events) {
	m_identity = flow_identity_cache{
		.stream_key = make_stream_key(sid),
		.flow_key = make_flow_key(sid, m_fid),
	};

	m_text = flow_text_cache{
		.role = to_string(m_fid.role),
		.src = to_string(m_fid.src),
		.dst = to_string(m_fid.dst),
	};

	m_event.source = stream_json::make_flow_event_source("RTP",
	                                                        m_fid.interface_id,
	                                                        m_interface_name,
	                                                        m_identity.stream_key,
	                                                        m_identity.flow_key,
	                                                        m_fid.vlan);
}

void flow::emit_detected(double now) {
	m_events.emit(make_event(now, "flow_detected", json{
		{"interface_id", m_fid.interface_id},
		{"role", m_text.role},
		{"endpoint", {
			{"src", m_text.src},
			{"dst", m_text.dst},
		}},
	}));
}

void flow::emit_lost(double now) {
	m_events.emit(make_event(now, "flow_lost", json{
		{"interface_id", m_fid.interface_id},
		{"role", m_text.role},
		{"endpoint", {
			{"src", m_text.src},
			{"dst", m_text.dst},
		}},
		{"last_seen", last_seen()},
	}));
}

int flow::process(const info &i) {
	touch(i.time_epoch);

	m_metrics.bitrate.update(i.time_epoch, i.frame_len);
	m_metrics.jitter.update(i.time_epoch, i.timestamp);
	m_metrics.interval.update(i.time_epoch);
	m_metrics.packet_rate.update(i.time_epoch);
	m_metrics.packet_count.inc();

	auto ex = m_metrics.seq_ext.update(static_cast<std::uint16_t>(i.seq));
	if(ex.updated) {
		auto seq_update = m_metrics.seq_stats.update(ex.ext_seq);
		m_event.packet.loss_gap_count += seq_update.gap_added;
		if(seq_update.duplicate) {
			++m_event.packet.duplicate_count;
		}
		if(seq_update.reordered) {
			++m_event.packet.reorder_count;
		}
	}

	auto tx = m_metrics.ts_ext.update(i.timestamp);
	if(tx.updated) {
		m_metrics.skew.update(i.time_epoch, tx.ext_ts);
	}

	return 0;
}

