	return subject;
}

json make_marker_detail(const event_record &e) {
	json detail = e.detail.is_object() ? e.detail : json::object();
	detail["event_type"] = e.type;
	detail["action"] = marker_action(e.type);
	if(e.source.is_object()) {
		for(const auto &key : {"alert_id", "severity", "target", "proto", "stream_key", "flow_key", "interface_id", "name"}) {
			if(e.source.contains(key) && !detail.contains(key)) {
				detail[key] = e.source[key];
			}
		}
	}
	if(!detail.contains("label")) {
		if(detail.contains("alert_id") && detail["alert_id"].is_string()) {
			detail["label"] = detail["alert_id"];
		}
		else if(detail.contains("metric") && detail["metric"].is_string()) {
			detail["label"] = detail["metric"];
		}
		else {
			detail["label"] = e.type;
		}
	}
	if(!detail.contains("severity")) {
		detail["severity"] = e.type == "alert_detected" ? "warning" : "info";
	}
	return detail;
}

