	static observe_mode read_observe_mode(const json &j);
	static vlan_match read_vlan_match(const json &j);
	static bool endpoint_port(const std::string &endpoint, unsigned &port);
	static bool parse_endpoint(const std::string &endpoint, ip_endpoint &out);
	static bool auto_decode_as(std::string_view proto, unsigned port, std::string &out);
	static bool proto_matches(std::string_view rule_proto, std::string_view observed_proto);
	static bool is_dedicated_proto(std::string_view proto);
	static bool vlan_matches(const vlan_match &rule_vlan, const tsv::vlan_info &packet_vlan);
	static bool endpoint_matches(const rule &r, const ip_endpoint &candidate);
	static bool endpoint_matches(const rule &r, const ip_endpoint &configured, const ip_endpoint &candidate);
	static bool host_matches(const rule &r, std::string_view host);
	return false;
}


std::vector<std::string> protocol_map::matching_target_ids(std::string_view proto,
                                                           const ip_endpoint &src,
                                                           const ip_endpoint &dst,
                                                           const tsv::vlan_info &vlan,
                                                           std::string_view host) const {
	std::vector<std::string> ids;
	for(const auto &r : m_rules) {
		if(r.id.empty() || !proto_matches(r.proto, proto) || !vlan_matches(r.vlan, vlan)) continue;
		if(endpoint_matches(r, src) || endpoint_matches(r, dst) || host_matches(r, host)) {
			if(std::find(ids.begin(), ids.end(), r.id) == ids.end()) ids.push_back(r.id);
		}
	}
	return ids;
}

std::string protocol_map::stream_display_name(const std::vector<std::string> &target_ids) const {
	std::string result;
	for(const auto &id : target_ids) {
		for(const auto &rule : m_rules) {
			if(rule.id != id || rule.target_type != "single" || rule.stream_name.empty()) continue;
			if(!result.empty()) return {};
			result = rule.stream_name;
			break;
		}
	}
	return result;
}

	return ids;
}

bool protocol_map::has_observable_host_rule(std::string_view proto, const tsv::vlan_info &vlan) const {
	for(const auto &r : m_rules) {
		if(!r.observe || r.hosts.empty()) {
			continue;
		}
		if(!proto_matches(r.proto, proto)) {
			continue;
		}
		if(!vlan_matches(r.vlan, vlan)) {
			continue;
		}
		return true;
	}
	return false;
}
