  return <aside className="alerts-profile-detail alerts-assignment-detail"><header><div><h3>{editing ? "Edit assignment" : assignmentSummary(assignment)}</h3><p>{editing ? "Changes stay local until Save assignment." : selectedProfiles.length + " assigned profiles"}</p></div>{editing ? <span className="alerts-detail-actions"><button type="button" className="maintenance-secondary-button" disabled={busy} onClick={onDelete}>Delete</button><button type="button" className="maintenance-secondary-button" disabled={busy} onClick={onCancel}>Cancel</button><button type="button" className="maintenance-save-button" disabled={busy} onClick={onSave}>Save assignment</button></span> : <button type="button" className="maintenance-secondary-button" disabled={busy} onClick={onEdit}>Edit</button>}</header>{editing ? <div className="alerts-profile-fields"><label>Scope<select value={draft.scope.kind} disabled={busy} onChange={(event) => setScope(event.target.value === "managed_target" ? { kind: "managed_target", target_id: "", target_type: "single" } : { kind: "protocol", proto: "RTP", target: "flow" })}><option value="protocol">Protocol default</option><option value="managed_target">Monitoring target</option></select></label>{draft.scope.kind === "managed_target" ? <><label>Target ID<TargetPicker value={draft.scope.target_id} targetType={draft.scope.target_type ?? "single"} targets={targets} busy={busy} onChange={(target_id, target_type) => setScope({ ...draft.scope, target_id, target_type } as AlertAssignment["scope"])} /></label><label>Target type<select value={draft.scope.target_type ?? "single"} disabled={busy} onChange={(event) => setScope({ ...draft.scope, target_type: event.target.value as "single" | "group" } as AlertAssignment["scope"])}><option value="single">Single</option><option value="group">Group</option></select></label></> : <label>Protocol<select value={draft.scope.proto ?? ""} disabled={busy} onChange={(event) => setScope({ ...draft.scope, proto: event.target.value } a