import type { TopologyEdge, TopologyNode, TopologyRelationFlowsResponse, TopologySnapshot } from "../types";

type CachedEdge = { edge: TopologyEdge; firstSeen: number; lastSeen: number; lostAt?: number };
type CachedNode = { node: TopologyNode; firstSeen: number; lastSeen: number };
type CachedFlow = CachedEdge & { relationId: string };

/**
 * Keeps raw flows for a selected relation, while publishing a bounded service
 * relation map to every Live client. Historical topology remains raw elsewhere.
 */
export class TopologyDisplay {
  private readonly edges = new Map<string, CachedEdge>();
  private readonly nodes = new Map<string, CachedNode>();
  private readonly flows = new Map<string, CachedFlow>();
  private lastObservedAt?: number;

  constructor(
    private readonly staleRetentionSec: number,
    private readonly maxStaleEdges: number,
    private readonly maxDetailFlowsPerRelation = 200
  ) {}

  apply(snapshot: TopologySnapshot): TopologySnapshot {
    const observedAt = finiteTime(snapshot.time, this.lastObservedAt ?? 0);
    if (this.lastObservedAt !== undefined && observedAt < this.lastObservedAt) return this.snapshot(this.lastObservedAt);
    this.lastObservedAt = observedAt;
    this.updateFlows(snapshot.edges, observedAt);
    return this.applyRelations(this.aggregateActiveRelations(observedAt), observedAt);
  }

  get(): TopologySnapshot | undefined {
    return this.lastObservedAt === undefined ? undefined : this.snapshot(this.lastObservedAt);
  }

  getRelationFlows(relationId: string, state: "active" | "all", limit: number): TopologyRelationFlowsResponse | undefined {
    const relation = this.get()?.edges.find((edge) => edge.id === relationId);
    if (!relation) return undefined;
    const all = [...this.flows.values()]
      .filter((flow) => flow.relationId === relationId)
      .sort((left, right) => (right.lastSeen - left.lastSeen) || left.edge.id.localeCompare(right.edge.id));
    const active = all.filter((flow) => flow.edge.state === "active");
    const visible = state === "active" ? active : all;
    return {
      relation,
      flows: visible.slice(0, Math.max(1, limit)).map(({ edge }) => ({ ...edge })),
      total: all.length,
      active: active.length,
      stale: all.length - active.length,
      nextCursor: visible.length > limit ? String(limit) : undefined
    };
  }

  private updateFlows(sourceEdges: TopologyEdge[], observedAt: number) {
    const activeIds = new Set<string>();
    for (const source of sourceEdges) {
      if (!source.id) continue;
      const previous = this.flows.get(source.id);
      const relationId = relationIdFor(source);
      this.flows.set(source.id, {
        relationId,
        firstSeen: previous?.firstSeen ?? observedAt,
        lastSeen: observedAt,
        edge: { ...source, state: "active", first_seen: previous?.firstSeen ?? observedAt, last_seen: observedAt }
      });
      activeIds.add(source.id);
    }
    for (const [id, cached] of this.flows) {
      if (activeIds.has(id)) continue;
      const lostAt = cached.lostAt ?? observedAt;
      const { alert: _alert, ...withoutAlert } = cached.edge;
      this.flows.set(id, {
        ...cached,
        lostAt,
        edge: { ...withoutAlert, state: "stale", first_seen: cached.firstSeen, last_seen: cached.lastSeen, lost_at: lostAt }
      });
    }
    this.pruneFlows(observedAt);
  }

  private aggregateActiveRelations(observedAt: number): TopologySnapshot {
    const groups = new Map<string, CachedFlow[]>();
    for (const flow of this.flows.values()) groups.set(flow.relationId, [...(groups.get(flow.relationId) ?? []), flow]);
    const edges: TopologyEdge[] = [];
    for (const [id, flows] of groups) {
      const active = flows.filter((flow) => flow.edge.state === "active");
      if (active.length === 0) continue;
      const template = active[0].edge;
      const endpoints = relationEndpoints(template);
      const metrics = sumMetrics(active.map((flow) => flow.edge.metrics));
      const alert = summarizeAlerts(active.map((flow) => flow.edge.alert));
      edges.push({
        id,
        type: "service-relation",
        src: endpoints.srcId,
        dst: endpoints.dstId,
        proto: template.proto,
        transport: template.transport,
        state: "active",
        first_seen: Math.min(...flows.map((flow) => flow.firstSeen)),
        last_seen: Math.max(...flows.map((flow) => flow.lastSeen)),
        scope: template.scope,
        identity: { stream_key: template.identity?.stream_key },
        endpoint: { src: endpoints.src, dst: endpoints.dst },
        display: template.display,
        flow_summary: summarizeFlows(flows),
        ...(Object.keys(metrics).length > 0 ? { metrics } : {}),
        ...(alert ? { alert } : {})
      });
    }
    return { time: observedAt, nodes: [], edges };
  }

  private applyRelations(snapshot: TopologySnapshot, observedAt: number): TopologySnapshot {
    const activeEdgeIds = new Set<string>();
    const activeNodeIds = new Set<string>();
    for (const sourceEdge of snapshot.edges) {
      const previous = this.edges.get(sourceEdge.id);
      const edge = { ...sourceEdge, state: "active", first_seen: previous?.firstSeen ?? observedAt, last_seen: observedAt };
      this.edges.set(edge.id, { edge, firstSeen: previous?.firstSeen ?? observedAt, lastSeen: observedAt });
      activeEdgeIds.add(edge.id);
      activeNodeIds.add(edge.src);
      activeNodeIds.add(edge.dst);
    }
    for (const [id, cached] of this.edges) {
      if (activeEdgeIds.has(id)) continue;
      const lostAt = cached.lostAt ?? observedAt;
      const { alert: _alert, ...withoutAlert } = cached.edge;
      const summary = this.flowSummary(id);
      this.edges.set(id, { ...cached, lostAt, edge: {
        ...withoutAlert,
        state: "stale",
        first_seen: cached.firstSeen,
        last_seen: cached.lastSeen,
        lost_at: lostAt,
        flow_summary: summary
      } });
    }
    this.pruneStaleEdges(observedAt);
    return this.snapshot(observedAt, activeNodeIds);
  }

  private pruneFlows(observedAt: number) {
    for (const [id, flow] of this.flows) if (flow.lostAt !== undefined && observedAt - flow.lostAt >= this.staleRetentionSec) this.flows.delete(id);
    const groups = new Map<string, CachedFlow[]>();
    for (const flow of this.flows.values()) if (flow.edge.state === "stale") groups.set(flow.relationId, [...(groups.get(flow.relationId) ?? []), flow]);
    for (const stale of groups.values()) {
      stale.sort((left, right) => (right.lastSeen - left.lastSeen) || left.edge.id.localeCompare(right.edge.id));
      for (const flow of stale.slice(this.maxDetailFlowsPerRelation)) this.flows.delete(flow.edge.id);
    }
  }

  private flowSummary(relationId: string) {
    const flows = [...this.flows.values()].filter((flow) => flow.relationId === relationId);
    return summarizeFlows(flows);
  }

  private pruneStaleEdges(observedAt: number) {
    const stale = [...this.edges.entries()].filter(([, cached]) => cached.lostAt !== undefined)
      .sort(([leftId, left], [rightId, right]) => (left.lostAt! - right.lostAt!) || leftId.localeCompare(rightId));
    for (const [id, cached] of stale) if (observedAt - cached.lostAt! >= this.staleRetentionSec) this.edges.delete(id);
    const remaining = [...this.edges.entries()].filter(([, cached]) => cached.lostAt !== undefined)
      .sort(([leftId, left], [rightId, right]) => (left.lostAt! - right.lostAt!) || leftId.localeCompare(rightId));
    for (const [id] of remaining.slice(0, Math.max(0, remaining.length - this.maxStaleEdges))) this.edges.delete(id);
  }

  private snapshot(time: number, activeNodeIds = new Set<string>()): TopologySnapshot {
    const referenced = new Set<string>();
    for (const { edge } of this.edges.values()) { referenced.add(edge.src); referenced.add(edge.dst); }
    const nodes: TopologyNode[] = [];
    for (const id of [...referenced].sort()) {
      const cached = this.nodes.get(id);
      const node = cached?.node ?? nodeForId(id);
      const active = activeNodeIds.has(id) || [...this.edges.values()].some(({ edge }) => edge.state === "active" && (edge.src === id || edge.dst === id));
      const { alert: _alert, ...withoutAlert } = node;
      nodes.push({ ...(active ? node : withoutAlert), state: active ? "active" : "stale", first_seen: cached?.firstSeen ?? time, last_seen: cached?.lastSeen ?? time });
    }
    const edges = [...this.edges.values()].map(({ edge }) => ({ ...edge })).sort((left, right) => left.id.localeCompare(right.id));
    return { time, nodes, edges };
  }
}

function relationIdFor(edge: TopologyEdge) {
  const endpoints = relationEndpoints(edge);
  const scope = JSON.stringify(edge.scope ?? {});
  return `relation:${[scope, edge.proto ?? "", edge.transport ?? "", edge.identity?.stream_key ?? "", endpoints.src, endpoints.dst].join("|")}`;
}

function relationEndpoints(edge: TopologyEdge) {
  const src = endpointString(edge.endpoint?.src) ?? edge.src;
  const dst = endpointString(edge.endpoint?.dst) ?? edge.dst;
  const service = edge.display?.service_endpoint || dst;
  const fromService = edge.display?.direction === "from-service" || service === src;
  const peer = fromService ? dst : src;
  const transport = edge.transport ?? "unknown";
  const serviceNode = endpointNodeId(service, transport, true);
  const peerNode = endpointNodeId(hostOnly(peer), transport, false);
  /* A service relation is bidirectional: direction belongs to each raw flow. */
  return { src: hostOnly(peer), dst: service, srcId: peerNode, dstId: serviceNode };
}

function summarizeFlows(flows: CachedFlow[]) {
  let active = 0;
  let toService = 0;
  let fromService = 0;
  for (const flow of flows) {
    if (flow.edge.state !== "active") continue;
    active += 1;
    if (flowDirection(flow.edge) === "from-service") fromService += 1;
    else toService += 1;
