export type AlertAssignment = { scope: AlertAssignmentScope; profile_ids: string[]; overrides?: Record<string, Partial<AlertRule>> };
export type AlertsDocument = { _note?: string; alerts?: AlertRule[]; rules?: AlertRule[]; profiles?: AlertProfile[]; assignments?: AlertAssignment[] };
export type MonitoringTargetDefinition = { id: string; target_type: "single" | "group"; proto: string; title?: string };
export type AlertMetricDefinition = { key: string; description?: string; unit?: string; preview: boolean };
export type AlertsResponse = {
  revision: string;
  path: string;
  document: AlertsDocument;
  metrics: AlertMetricDefinition[];
  protocols: string[];
  apply: "restart_required";
  monitoringTargets: MonitoringTargetDefinition[];
};

export class AlertsConflictError extends Error {}
export class AlertsValidationError extends Error {}

export class AlertsSettings {
  constructor(private readonly stmConfigFile: string) {}

  async get(): Promise<AlertsResponse> {
    const configured = await this.readConfiguredAlerts();
    const schemaText = await readFile(this.schemaFile(), "utf8");
    const document = validateDocument(parseJson(configured.alertsText, "alerts config"));
    const schema = parseSchema(parseJson(schemaText, "alerts schema"));
    const monitoring = await this.readMonitoringTargets(configured.stmConfigText);
    return {
      revision: revisionOf(configured.stmConfigText, configured.alertsText, schemaText, monitoring.sourceText),
      path: configured.relativePath,
      document,
      metrics: schema.metrics,
      protocols: schema.protocols,
      apply: "restart_required",
      monitoringTargets: monitoring.targets
    };
  }

  async update(input: { revision: unknown; document: unknown }): Promise<AlertsResponse> {
    const current = await this.get();
    if (typeof input.revision !== "string" || input.revision !== current.revision) {
      throw new AlertsConflictError("alerts config changed on the server; reload before applying");
    }
    const document = validateDocument(input.document, current.metrics, current.protocols);
    const configured = await this.readConfiguredAlerts();
    await atomicWrite(configured.alertsFile, JSON.stringify(document, null, 2) + "\n");
    return this.get();
  }

  private async readConfiguredAlerts() {
    const stmConfigText = await readFile(this.stmConfigFile, "utf8");
    const stmConfig = parseObject(stmConfigText, "STM config");
    const configs = stmConfig.configs && typeof stmConfig.configs === "object" && !Array.isArray(stmConfig.configs)
      ? stmConfig.configs as Record<string, unknown> : undefined;
    const configuredPath = configs?.alerts ?? configs?.alert_config;
    if (typeof configuredPath !== "string" || !configuredPath.trim()) {
      throw new AlertsValidationError("configs.alerts must be a non-empty relative path");
    }
    const relativePath = validateRelativePath(configuredPath);
    const alertsFile = path.resolve(path.dirname(this.stmConfigFile), relativePath);
    const alertsText = await readFile(alertsFile, "utf8");
    return { stmConfigText, relativePath, alertsFile, alertsText };
  }

  private async readMonitoringTargets(stmConfigText: string): Promise<{ targets: MonitoringTargetDefinition[]; sourceText: string }> {
    const stmConfig = parseObject(stmConfigText, "STM config");
    const configs = stmConfig.configs && typeof stmConfig.configs === "object" && !Array.isArray(stmConfig.configs) ? stmConfig.configs as Record<string, unknown> : undefined;
    const configuredPath = configs?.protocol_map;
    if (typeof configuredPath !== "string" || !configuredPath.trim()) return { targets: [], sourceText: "" };
    const sourceText = await readFile(path.resolve(path.dirname(this.stmConfigFile), validateRelativePath(configuredPath)), "utf8");
    const map = parseObject(sourceText, "protocol map");
    const protocols = Array.isArray(map.protocols) ? map.protocols : [];
    const targets = protocols.flatMap((item): MonitoringTargetDefinition[] => {
      if (!item || typeof item !== "object" || Array.isArray(item)) return [];
      const rule = item as Record<string, unknown>;
      if (typeof rule.id !== "string" || !rule.id.trim() || typeof rule.proto !== "string") return [];
      return [{ id: rule.id, proto: rule.proto, target_type: rule.target_type === "group" ? "group" : "single", ...(typeof rule.stream_name === "string" ? { title: rule.stream_name } : {}) }];
    });
    return { targets, sourceText };
  }

  private schemaFile() { return path.resolve(path.dirname(this.stmConfigFile), "alerts_config.schema.json"); }
}

function parseJson(text: string, label: string): unknown {
  try { return JSON.parse(text) as unknown; }
  catch (error) { throw new AlertsValidationError("invalid " + label + ": " + String(error)); }
}

function parseObject(text: string, label: string): Record<string, unknown> {
  const value = parseJson(text, label);
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new AlertsValidationError("invalid " + label + ": must be an object");
  return value as Record<string, unknown>;
}

function validateRelativePath(value: unknown) {
  if (typeof value !== "string" || !value.trim()) throw new AlertsValidationError("alerts config path is required");
  const normalized = path.posix.normalize(value.trim());
  if (path.isAbsolute(normalized) || normalized === ".." || normalized.startsWith("../")) {
    throw new AlertsValidationError("alerts config path must remain under the STM config directory");
  }
  return normalized;
}

function validateDocument(value: unknown, metrics?: AlertMetricDefinition[], protocols?: string[]): AlertsDocument {
  const root = Array.isArray(value) ? { alerts: value } : value;
  if (!root || typeof root !== "object" || Array.isArray(root)) throw new AlertsValidationError("alerts config must be an object or array");
  const record = root as Record<string, unknown>;
  if (record._note !== undefined && typeof record._note !== "string") throw new AlertsValidationError("_note must be a string");
  const note = typeof record._note === "string" ? { _note: record._note } : {};
  if (Array.isArray(record.alerts) && record.rules === undefined) {
    const alerts = record.alerts.map((rule, index) => validateRule(rule, index, metrics, protocols));
    ensureUniqueIds(alerts, "alert rule");
    return { ...note, alerts };
  }
  if (!Array.isArray(record.rules) || !Array.isArray(record.profiles) || !Array.isArray(record.assignments)) throw new AlertsValidationError("profile format requires rules, profiles, and assignments arrays");
  const rules = record.rules.map((rule, index) => validateRule(rule, index, metrics, protocols));
  ensureUniqueIds(rules, "rule");
  const ruleIds = new Set(rules.map((rule) => rule.id));
  const profiles = record.profiles.map((profile, index) => validateProfile(profile, index, ruleIds));
  ensureUniqueIds(profiles, "profile");
  const profileIds = new Set(profiles.map((profile) => profile.id));
  const assignments = record.assignments.map((assignment, index) => validateAssignment(assignment, index, profileIds, ruleIds, protocols));
  return { ...note, rules, profiles, assignments };
}

function ensureUniqueIds(items: Array<{ id: string }>, label: string) { const ids = new Set<string>(); for (const item of items) { if (ids.has(item.id)) throw new AlertsValidationError(label + " ids must be unique: " + item.id); ids.add(item.id); } }
function validateProfile(value: unknown, index: number, ruleIds: Set<string>): AlertProfile { const prefix = "profile " + (index + 1); if (!value || typeof value !== "object" || Array.isArray(value)) throw new AlertsValidationError(prefix + " must be an object"); const profile = value as Record<string, unknown>; if (typeof profile.id !== "string" || !profile.id.trim()) throw new AlertsValidationError(prefix + ": id is required"); if (profile.title !== undefined && typeof profile.title !== "string") throw new AlertsValidationError(prefix + ": title must be a string"); if (!Array.isArray(profile.rule_ids) || profile.rule_ids.some((id) => typeof id !== "string" || !ruleIds.has(id))) throw new AlertsValidationError(prefix + ": rule_ids must refer to defined rules"); return { id: profile.id, ...(typeof profile.title === "string" ? { title: profile.title } : {}), rule_ids: profile.rule_ids as string[] }; }
function validateAssignment(value: unknown, index: number, profileIds: Set<string>, ruleIds: Set<string>, protocols?: string[]): AlertAssignment { const prefix = "assignment " + (index + 1); if (!value || typeof value !== "object" || Array.isArray(value)) throw new AlertsValidationError(prefix + " must be an object"); const assignment = value as Record<string, unknown>; if (!Array.isArray(assignment.profile_ids) || assignment.profile_ids.some((id) => typeof id !== "string" || !profileIds.has(id))) throw new AlertsValidationError(prefix + ": profile_ids must refer to defined profiles"); const scope = assignment.scope; if (!scope || typeof scope !== "object" || Array.isArray(scope)) throw new AlertsValidationError(prefix + ": scope is required"); const s = scope as Record<string, unknown>; if (s.kind === "protocol") { if (s.proto !== undefined && (typeof s.proto !== "string" || (protocols && !protocols.includes(s.proto)))) throw new AlertsValidationError(prefix + ": invalid protocol scope"); if (s.target !== undefined && !["any", "flow", "stream", "interface"].includes(String(s.target))) throw new AlertsValidationError(prefix + ": invalid protocol target"); } else if (s.kind === "managed_target") { if (typeof s.target_id !== "string" || !s.target_id.trim()) throw new AlertsValidationError(prefix + ": managed target id is required"); if (s.target_type !== undefined && s.target_type !== "single" && s.target_type !== "group") throw new AlertsValidationError(prefix + ": invalid target type"); } else throw new AlertsValidationError(prefix + ": scope kind must be protocol or managed_target"); const overrides = assignment.overrides; if (overrides !== undefined) { if (!overrides || typeof overrides !== "object" || Array.isArray(overrides)) throw new AlertsValidationError(prefix + ": overrides must be an object"); for (const [ruleId, override] of Object.entries(overrides)) { if (!ruleIds.has(ruleId) || !override || typeof override !== "object" || Array.isArray(override)) throw new AlertsValidationError(prefix + ": invalid override"); validateOverride(override as Record<string, unknown>, prefix + ": override " + ruleId); } } return assignment as AlertAssignment; }

function validateOverride(value: Record<string, unknown>, prefix: string) { const permitted = new Set(["enabled", "severity", "error_threshold", "recover_threshold", "delta_threshold", "recover_after_sec"]); for (const [key, candidate] of Object.entries(value)) { if (!permitted.has(key)) throw new AlertsValidationError(prefix + ": unsupported field " + key); if (key === "enabled" && typeof candidate !== "boolean") throw new AlertsValidationError(prefix + ": enabled must be boolean"); if (key === "severity" && (typeof candidate !== "string" || !candidate.trim())) throw new AlertsValidationError(prefix + ": severity must be a non-empty string"); if (["error_threshold", "recover_threshold", "delta_threshold", "recover_after_sec"].includes(key) && (typeof candidate !== "number" || !Number.isFinite(candidate))) throw new AlertsValidationError(prefix + ": " + key + " must be a finite number"); } }

function validateRule(value: unknown, index: number, metrics?: AlertMetricDefinition[], protocols?: string[]): AlertRule {
  const prefix = "row " + (index + 1);
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new AlertsValidationError(prefix + " must be an object");
  const rule = value as Record<string, unknown>;
  if (typeof rule.id !== "string" || !rule.id.trim()) throw new AlertsValidationError(prefix + ": id is required");
  if (typeof rule.metric !== "string" || !rule.metric.trim()) throw new AlertsValidationError(prefix + ": metric is required");
  if (rule.enabled !== undefined && typeof rule.enabled !== "boolean") throw new AlertsValidationError(prefix + ": enabled must be boolean");
  if (rule.target !== undefined && !["any", "flow", "stream", "interface"].includes(String(rule.target))) throw new AlertsValidationError(prefix + ": invalid target");
  if (rule.proto !== undefined && typeof rule.proto !== "string") throw new AlertsValidationError(prefix + ": proto must be a string");
  if (typeof rule.proto === "string" && protocols && !protocols.includes(rule.proto)) throw new AlertsValidationError(prefix + ": protocol is not defined by the alerts schema");
  if (metrics && !metrics.some((metric) => metric.key === rule.metric)) throw new AlertsValidationError(prefix + ": metric is not defined by the alerts schema");
  if (rule.type !== undefined && !["threshold", "counter_delta"].includes(String(rule.type))) throw new AlertsValidationError(prefix + ": invalid type");
  if (rule.operator !== undefined && ![">", ">=", "<", "<=", "==", "!="].includes(String(rule.operator))) throw new AlertsValidationError(prefix + ": invalid operator");
  for (const key of ["error_threshold", "recover_threshold", "delta_threshold", "recover_after_sec"] as const) {
    if (rule[key] !== undefined && (typeof rule[key] !== "number" || !Number.isFinite(rule[key]))) throw new AlertsValidationError(prefix + ": " + key + " must be a finite number");
  }
  if (rule.recover_after_sec !== undefined && Number(rule.recover_after_sec) < 0) throw new AlertsValidationError(prefix + ": recover_after_sec must be at least zero");
  if (rule.severity !== undefined && (typeof rule.severity !== "string" || !rule.severity.trim())) throw new AlertsValidationError(prefix + ": severity must be a non-empty string");
  const type = rule.type ?? "threshold";
  if (type === "threshold" && rule.error_threshold === undefined) throw new AlertsValidationError(prefix + ": error_threshold is required for threshold rules");
  if (type === "counter_delta" && rule.delta_threshold === undefined) throw new AlertsValidationError(prefix + ": delta_threshold is required for counter_delta rules");
  return rule as AlertRule;
}

function parseSchema(value: unknown): { metrics: AlertMetricDefinition[]; protocols: string[] } {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new AlertsValidationError("invalid alerts schema: must be an object");
  const root = value as Record<string, unknown>;
  const properties = (((root.$defs as Record<string, unknown> | undefined)?.alertRule as Record<string, unknown> | undefined)?.properties as Record<string, unknown> | undefined);
  const metricItems = ((properties?.metric as Record<string, unknown> | undefined)?.oneOf);
  const protocols = ((properties?.proto as Record<string, unknown> | undefined)?.enum);
  if (!Array.isArray(metricItems) || !Array.isArray(protocols)) throw new AlertsValidationError("invalid alerts schema: metric or protocol definitions are missing");
  const metrics = metricItems.flatMap((item): AlertMetricDefinition[] => {
    if (!item || typeof item !== "object" || Array.isArray(item)) return [];
    const definition = item as Record<string, unknown>;
    return typeof definition.const === "string" ? [{
      key: definition.const,
      ...(typeof definition.description === "string" ? { description: definition.description } : {}),
      ...(typeof definition["x-unit"] === "string" ? { unit: definition["x-unit"] } : {}),
      preview: definition["x-ui-preview"] === true
    }] : [];
  }).sort((left, right) => left.key.localeCompare(right.key));
  return { metrics, protocols: protocols.filter((item): item is string => typeof item === "string") };
}

function revisionOf(...texts: string[]) { return createHash("sha256").update(texts.join("\\u0000")).digest("hex"); }
async function atomicWrite(file: string, contents: string) { await mkdir(path.dirname(file), { recursive: true }); const temp = path.join(path.dirname(file), "." + path.basename(file) + "." + process.pid + ".tmp"); await writeFile(temp, contents, "utf8"); await rename(temp, file); }
import { createHash } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";

export type ProtocolRule = {
  id?: string;
  target_type?: "single" | "group";
  enabled?: boolean;
  observe?: boolean;
  proto: string;
  endpoints?: string | string[];
  hosts?: string | string[];
  domains?: string | string[];
  decode_as?: string | string[];
  fec?: boolean;
  vlan?: number | string | null;
  stream_name?: string;
};

export type ProtocolMapDocument = {
  observe_mode?: "all" | "configured_only" | "configured_plus_other";
  protocols: ProtocolRule[];
};

export type ProtocolMapResponse = {
  revision: string;
  path: string;
  document: ProtocolMapDocument;
  apply: "restart_required";
};

export class ProtocolMapConflictError extends Error {}
export class ProtocolMapValidationError extends Error {}

export class ProtocolMapSettings {
  constructor(private readonly stmConfigFile: string) {}

  async get(): Promise<ProtocolMapResponse> {
    const stmConfigText = await readFile(this.stmConfigFile, "utf8");
    const stmConfig = parseObject(stmConfigText, "STM config");
    const configuredPath = stmConfig.configs && typeof stmConfig.configs === "object" && !Array.isArray(stmConfig.configs)
      ? (stmConfig.configs as Record<string, unknown>).protocol_map : undefined;
    if (typeof configuredPath !== "string" || !configuredPath.trim()) {
      throw new ProtocolMapValidationError("configs.protocol_map must be a non-empty relative path");
    }
    const relativePath = validateRelativePath(configuredPath);
    const mapFile = path.resolve(path.dirname(this.stmConfigFile), relativePath);
    const mapText = await readFile(mapFile, "utf8");
    const document = validateDocument(parseObject(mapText, "protocol map"));
    return { revision: revisionOf(stmConfigText, mapText), path: relativePath, document, apply: "restart_required" };
  }

  async update(input: { revision: unknown; path: unknown; document: unknown }): Promise<ProtocolMapResponse> {
    const current = await this.get();
    if (typeof input.revision !== "string" || input.revision !== current.revision) {
      throw new ProtocolMapConflictError("protocol map changed on the server; reload before applying");
    }
    const relativePath = validateRelativePath(input.path);
    const document = validateDocument(input.document);
    const stmConfigText = await readFile(this.stmConfigFile, "utf8");
    const stmConfig = parseObject(stmConfigText, "STM config");
    const configs = stmConfig.configs && typeof stmConfig.configs === "object" && !Array.isArray(stmConfig.configs)
      ? { ...(stmConfig.configs as Record<string, unknown>) } : {};
    configs.protocol_map = relativePath;
    stmConfig.configs = configs;
    const mapFile = path.resolve(path.dirname(this.stmConfigFile), relativePath);
    await atomicWrite(mapFile, `${JSON.stringify(document, null, 2)}\n`);
    await atomicWrite(this.stmConfigFile, `${JSON.stringify(stmConfig, null, 2)}\n`);
    return this.get();
  }
}

function parseObject(text: string, label: string): Record<string, unknown> {
  try {
    const parsed = JSON.parse(text) as unknown;
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("must be an object");
    return parsed as Record<string, unknown>;
  } catch (error) {
    throw new ProtocolMapValidationError(`invalid ${label}: ${String(error)}`);
  }
}

function validateRelativePath(value: unknown) {
  if (typeof value !== "string" || !value.trim()) throw new ProtocolMapValidationError("protocol map path is required");
  const normalized = path.posix.normalize(value.trim());
  if (path.isAbsolute(normalized) || normalized === ".." || normalized.startsWith("../")) {
    throw new ProtocolMapValidationError("protocol map path must remain under the STM config directory");
  }
  return normalized;
}

function validateDocument(value: unknown): ProtocolMapDocument {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new ProtocolMapValidationError("protocol map must be an object");
  const root = value as Record<string, unknown>;
  if (root.observe_mode !== undefined && !["all", "configured_only", "configured_plus_other"].includes(String(root.observe_mode))) {
    throw new ProtocolMapValidationError("invalid observe_mode");
  }
  if (!Array.isArray(root.protocols)) throw new ProtocolMapValidationError("protocols must be an array");
  const protocols = root.protocols.map((item, index) => validateRule(item, index));
  const targetIds = new Set<string>();
  for (const rule of protocols) {
    if (rule.id && targetIds.has(rule.id)) throw new ProtocolMapValidationError("Monitoring Target IDs must be unique: " + rule.id);
    if (rule.id) targetIds.add(rule.id);
  }
  return { ...(root.observe_mode === undefined ? {} : { observe_mode: root.observe_mode as ProtocolMapDocument["observe_mode"] }), protocols };
}

function validateRule(value: unknown, index: number): ProtocolRule {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new ProtocolMapValidationError(`row ${index + 1} must be an object`);
  const rule = value as Record<string, unknown>;
  if (rule.id !== undefined && (typeof rule.id !== "string" || !isTargetId(rule.id))) throw new ProtocolMapValidationError("row " + (index + 1) + ": id must use letters, numbers, dot, underscore, or hyphen");
  if (rule.target_type !== undefined && rule.target_type !== "single" && rule.target_type !== "group") throw new ProtocolMapValidationError("row " + (index + 1) + ": target type must be single or group");
  if (rule.target_type !== undefined && !rule.id) throw new ProtocolMapValidationError("row " + (index + 1) + ": target type requires an id");
  if (typeof rule.proto !== "string" || !["RTP", "SRT", "HLS"].includes(rule.proto.toUpperCase())) throw new ProtocolMapValidationError(`row ${index + 1}: protocol must be RTP, SRT, or HLS`);
  for (const key of ["enabled", "observe", "fec"] as const) if (rule[key] !== undefined && typeof rule[key] !== "boolean") throw new ProtocolMapValidationError(`row ${index + 1}: ${key} must be boolean`);
  for (const key of ["endpoints", "hosts", "domains", "decode_as"] as const) validateStrings(rule[key], `row ${index + 1}: ${key}`);
  if (rule.stream_name !== undefined && (typeof rule.stream_name !== "string" || !rule.stream_name.trim() || rule.stream_name.length > 128)) throw new ProtocolMapValidationError(`row ${index + 1}: stream_name must be 1-128 characters`);
  if (rule.stream_name !== undefined && !rule.id) throw new ProtocolMapValidationError("row " + (index + 1) + ": stream_name requires an id");
  if (rule.vlan !== undefined && rule.vlan !== null && (!Number.isInteger(typeof rule.vlan === "string" ? Number(rule.vlan) : rule.vlan) || Number(rule.vlan) < 0 || Number(rule.vlan) > 4094)) throw new ProtocolMapValidationError(`row ${index + 1}: VLAN must be 0-4094`);
  const endpoints = asStrings(rule.endpoints);
  const hosts = asStrings(rule.hosts).concat(asStrings(rule.domains));
  if (rule.enabled !== false && !endpoints.length && !hosts.length) throw new ProtocolMapValidationError(`row ${index + 1}: an endpoint or host is required while enabled`);
  if (["RTP", "SRT"].includes(rule.proto.toUpperCase()) && hosts.length) throw new ProtocolMapValidationError(`row ${index + 1}: hosts are supported by HLS only`);
  if (rule.proto.toUpperCase() === "HLS" && endpoints.length && hosts.length) throw new ProtocolMapValidationError(`row ${index + 1}: choose an endpoint or host, not both`);
  return rule as ProtocolRule;
}

function asStrings(value: unknown) { return typeof value === "string" ? [value] : Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : []; }
function validateStrings(value: unknown, label: string) { if (value !== undefined && !asStrings(value).length) throw new ProtocolMapValidationError(`${label} must be a string or non-empty string array`); }
function isTargetId(value: string) { return value.length <= 128 && /^[A-Za-z0-9][A-Za-z0-9._-]*/.exec(value)?.[0] === value; }
function revisionOf(...texts: string[]) { return createHash("sha256").update(texts.join("\u0000")).digest("hex"); }
async function atomicWrite(file: string, contents: string) { await mkdir(path.dirname(file), { recursive: true }); const temp = path.join(path.dirname(file), `.${path.basename(file)}.${process.pid}.tmp`); await writeFile(temp, contents, "utf8"); await rename(temp, file); }

