export type AlertTarget = "any" | "flow" | "stream" | "interface";
export type AlertRuleType = "threshold" | "counter_delta";
export type AlertOperator = ">" | ">=" | "<" | "<=" | "==" | "!=";

export type AlertRule = {
  id: string;
  enabled?: boolean;
  target?: AlertTarget;
  proto?: string;
  metric: string;
  type?: AlertRuleType;
  operator?: AlertOperator;
  error_threshold?: number;
  recover_threshold?: number;
  delta_threshold?: number;
  recover_after_sec?: number;
  severity?: string;
};

export type AlertProfile = { id: string; title?: string; rule_ids: string[] };
export type AlertAssignmentScope = { kind: "protocol"; proto?: string; target?: AlertTarget } | { kind: "managed_target"; target_id: string; target_type?: "single" | "group" };
