  ensureUniqueIds(rules, "rule");
  const ruleIds = new Set(rules.map((rule) => rule.id));
  const profiles = record.profiles.map((profile, index) => validateProfile(profile, index, ruleIds));
  ensureUniqueIds(profiles, "profile");
  const profileIds = new Set(profiles.map((profile) => profile.id));
  const assignments = record.assignments.map((assignment, index) => validateAssignment(assignment, index, profileIds, ruleIds, protocols));
