			r.id = entry["id"].get<std::string>();
			if(!target_ids.insert(r.id).second) { std::cerr << "protocol_map: duplicate target id " << r.id << std::endl; return -1; }
		}
		if(entry.contains("target_type")) {
			if(!entry["target_type"].is_string() || (entry["target_type"] != "single" && entry["target_type"] != "group")) { std::cerr << "protocol_map: target_type must be single or group" << std::endl; return -1; }
			if(r.id.empty()) { std::cerr << "protocol_map: target_type requires id" << std::endl; return -1; }
			r.target_type = entry["target_type"].get<std::string>();
		}
		r.proto = entry["proto"].get<std::string>();
		r.enabled = read_bool(entry, "enabled", true);
		if(entry.contains("stream_name") && entry["stream_name"].is_string()) {
			r.stream_name = entry["stream_name"].get<std::string>();
		}
