.protocol-map-frame { max-width: none; }
.protocol-map-controls, .protocol-map-row-actions { display: flex; flex-wrap: wrap; gap: var(--space-3); padding: var(--space-3); }
.protocol-map-controls label { display: grid; gap: var(--space-1); color: var(--muted); font-size: var(--font-size-xs); font-weight: 700; }
.protocol-map-controls input, .protocol-map-controls select { min-width: 250px; min-height: var(--control-height); padding: 0 var(--space-2); border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--surface-muted); color: var(--text-strong); }
.protocol-map-table { min-width: 1300px; }
.protocol-map-table input { width: 150px; }
.protocol-map-table td:nth-child(6) input { width: 86px; }
.protocol-map-table td:nth-child(7) input { width: 76px; margin-left: var(--space-1); }
.protocol-map-notice { padding: var(--space-3); border: 1px solid var(--warning); border-radius: var(--radius-md); background: var(--warning-soft); color: var(--warning); }

.alerts-frame { max-width: none; }
.alerts-toolbar { display: grid; grid-template-columns: minmax(0, 1fr) minmax(240px, 320px); gap: var(--space-3); }
.alerts-policy-rules { display: grid; gap: var(--space-3); padding-top: var(--space-3); }
.alerts-policy-rules > .alerts-toolbar { padding: 0 var(--space-3); }
.alerts-toolbar > input { width: 100%; min-width: 0; min-height: var(--control-height); padding: 0 var(--space-2); border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--surface-muted); color: var(--text-strong); }
.alerts-tabs { display: flex; flex-wrap: wrap; align-items: stretch; gap: 0; border-bottom: 1px solid var(--line); }
.alerts-tab { position: relative; display: inline-flex; min-height: var(--control-height); align-items: center; gap: 7px; padding: 0 var(--space-3); border: 0; border-radius: 0; background: transparent; color: var(--muted); cursor: pointer; font-weight: 700; }
.alerts-tab:hover { color: var(--text-strong); }
.alerts-tab.is-active { color: var(--accent); }
.alerts-tab.is-active::before { position: absolute; top: 0; right: 0; left: 0; height: 3px; background: var(--accent); content: ""; }
.alerts-tab span { min-width: 0; padding: 0; border-radius: 0; background: transparent; color: currentColor; font-size: var(--font-size-xs); text-align: center; }
.alerts-metric-search { display: grid; gap: var(--space-1); color: var(--muted); font-size: var(--font-size-xs); font-weight: 700; }
.alerts-metric-search input { min-width: 0; width: 100%; min-height: var(--control-height); padding: 0 var(--space-2); border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--surface-muted); color: var(--text-strong); }
