import { useEffect, useState, type FormEvent } from "react";
import { getAlertsSettings, getProtocolMapSettings, saveAlertsSettings, saveProtocolMapSettings } from "../api/client";
import type { AlertAssignment, AlertsDocument, AlertsResponse, ProtocolMapDocument, ProtocolMapResponse, ProtocolRule } from "../types/api";
import { Icon } from "./ui/Icon";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

type Row = Omit<ProtocolRule, "proto"> & { proto: ProtocolRule["proto"] | "RTP-FEC"; target: "endpoint" | "host"; value: string; port: string; vlanMode: "any" | "untagged" | "id"; vlanId: string };

const modes = ["all", "configured_only", "configured_plus_other"] as const;

export function ProtocolMapPane() {
  const [settings, setSettings] = useState<ProtocolMapResponse | null>(null);
  const [alertSettings, setAlertSettings] = useState<AlertsResponse | null>(null);
  const [path, setPath] = useState("");
  const [mode, setMode] = useState<ProtocolMapDocument["observe_mode"]>("all");
  const [rows, setRows] = useState<Row[]>([]);
  const [assignments, setAssignments] = useState<AlertAssignment[]>([]);
  const [profileTargetId, setProfileTargetId] = useState<string | null>(null);
  const [state, setState] = useState<"loading" | "idle" | "saving" | "saved" | "error">("loading");
  const [message, setMessage] = useState("");
  const locked = mode === "all";
  const profiles = alertSettings?.document.profiles ?? [];
  const profileTarget = rows.find((row) => row.id === profileTargetId) ?? null;

  const load = () => {
    setState("loading");
    void Promise.all([getProtocolMapSettings(), getAlertsSettings()]).then(([next, alerts]) => {
      setSettings(next); setAlertSettings(alerts); setPath(next.path); setMode(next.document.observe_mode ?? "all"); setRows(next.document.protocols.map(toRow)); setAssignments(alerts.document.assignments ?? []); setState("idle"); setMessage("");
    }).catch((error: unknown) => { setState("error"); setMessage(error instanceof Error ? error.message : "Failed to load Monitoring targets"); });
  };
  useEffect(load, []);

  const updateRow = (index: number, patch: Partial<Row>) => setRows((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, ...patch } : row));
  const removeRow = (index: number) => {
    const id = rows[index]?.id;
    setRows((current) => current.filter((_, rowIndex) => rowIndex !== index));
    if (id) setAssignments((current) => current.filter((assignment) => assignment.scope.kind !== "managed_target" || assignment.scope.target_id !== id));
  };
  const addRow = () => setRows((current) => [...current, { enabled: true, observe: true, id: newTargetId(), target_type: "single", target_name: "", proto: "RTP", target: "endpoint", value: "", port: "", vlanMode: "any", vlanId: "" }]);
  const assignedProfiles = (id: string) => assignments.find((assignment) => assignment.scope.kind === "managed_target" && assignment.scope.target_id === id)?.profile_ids ?? [];
  const setAssignedProfiles = (row: Row, profileIds: string[]) => setAssignments((current) => {
    const index = current.findIndex((assignment) => assignment.scope.kind === "managed_target" && assignment.scope.target_id === row.id);
    if (!profileIds.length) return index < 0 ? current : current.filter((_, itemIndex) => itemIndex !== index);
    const next = { scope: { kind: "managed_target" as const, target_id: row.id ?? newTargetId(), target_type: row.target_type ?? "single" }, profile_ids: profileIds };
    return index < 0 ? [...current, next] : current.map((assignment, itemIndex) => itemIndex === index ? { ...assignment, ...next } : assignment);
  });

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings) return;
    setState("saving"); setMessage("");
    const document: ProtocolMapDocument = { observe_mode: mode, protocols: rows.map(fromRow) };
    const alertDocument = alertSettings ? alertsDocument(alertSettings.document, assignments) : null;
    const saveAlerts = alertSettings && alertDocument && JSON.stringify(alertSettings.document.assignments ?? []) !== JSON.stringify(assignments)
      ? saveAlertsSettings(alertSettings.revision, alertDocument).then(setAlertSettings)
      : Promise.resolve();
    void saveAlerts.then(() => saveProtocolMapSettings(settings.revision, path, document)).then((next) => {
      setSettings(next); setPath(next.path); setMode(next.document.observe_mode ?? "all"); setRows(next.document.protocols.map(toRow)); setState("saved"); setMessage("Saved. Restart STM to apply the new Monitoring targets and alert assignments.");
    }).catch((error: unknown) => { setState("error"); setMessage(error instanceof Error ? error.message : "Failed to apply Monitoring targets"); });
  };

  return <PaneFrame className="maintenance-frame protocol-map-frame maintenance-floating-actions-frame" header={<PaneHeader title="Monitoring targets" icon="protocolMap" meta="STM classification, display names, and alert profile assignment" actions={<button type="button" className="maintenance-secondary-button button-with-icon" onClick={load} disabled={state === "loading" || state === "saving"}><Icon name="reload" size={16} />Reload</button>} />}>
    <form className="maintenance-form maintenance-form-with-floating-actions" onSubmit={submit}><div className="maintenance-form-content">
      <div className="maintenance-intro">Target name identifies this monitoring setting. Stream name is the label shown for a matched stream. Alert profiles can be assigned here; leaving it empty uses the protocol default. STM restart is required before changes take effect.</div>
      <section className="maintenance-section"><div className="maintenance-section-copy"><h2>Protocol map file</h2><p>Path relative to the STM unified config file.</p></div><div className="protocol-map-controls"><label>Path<input value={path} disabled={state === "saving"} onChange={(event) => setPath(event.target.value)} /></label><label>Observe mode<select value={mode} disabled={state === "saving"} onChange={(event) => setMode(event.target.value as ProtocolMapDocument["observe_mode"])}>{modes.map((item) => <option key={item} value={item}>{item}</option>)}</select></label></div></section>
      {locked && <div className="protocol-map-notice">all observes every classified stream. Saved rules remain available but cannot be edited in this mode.</div>}
      <section className="maintenance-section"><div className="maintenance-table-wrap"><table className="maintenance-table protocol-map-table"><thead><tr><th>#</th><th>Enabled</th><th>Target name</th><th>Type</th><th>Protocol</th><th>Target</th><th>Address / domain</th><th>Port</th><th>VLAN</th><th>Stream name</th><th>Alert profiles</th><th /></tr></thead><tbody>{rows.map((row, index) => <tr key={row.id ?? index}><td>{index + 1}</td><td><button type="button" role="switch" aria-checked={row.enabled !== false} className={`maintenance-switch ${row.enabled !== false ? "is-on" : "is-off"}`} disabled={locked || state === "saving"} onClick={() => updateRow(index, { enabled: row.enabled === false })}>{row.enabled === false ? "Off" : "On"}</button></td><td><input value={row.target_name ?? ""} placeholder="Studio A source" disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { target_name: event.target.value })} /></td><td><select value={row.target_type ?? "single"} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { target_type: event.target.value as ProtocolRule["target_type"] })}><option value="single">Single</option><option value="group">Group</option></select></td><td><select value={row.proto} disabled={locked || state === "saving"} onChange={(event) => { const proto = event.target.value as Row["proto"]; updateRow(index, { proto, target: proto === "HLS" ? row.target : "endpoint", fec: proto === "RTP-FEC" }); }}><option value="RTP">RTP</option><option value="RTP-FEC">RTP-FEC</option><option value="SRT">SRT</option><option value="HLS">HLS</option></select></td><td><select value={row.target} disabled={locked || state === "saving" || row.proto !== "HLS"} onChange={(event) => updateRow(index, { target: event.target.value as Row["target"], value: "", port: "" })}><option value="endpoint">Endpoint</option><option value="host">Host</option></select></td><td><input value={row.value} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { value: event.target.value })} placeholder={row.target === "host" ? "media.example.com" : "239.1.1.1"} /></td><td>{row.target === "endpoint" && <input type="number" min="1" max="65535" value={row.port} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { port: event.target.value })} />}</td><td><select value={row.vlanMode} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { vlanMode: event.target.value as Row["vlanMode"] })}><option value="any">Any</option><option value="untagged">Untagged</option><option value="id">ID</option></select>{row.vlanMode === "id" && <input type="number" min="0" max="4094" value={row.vlanId} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { vlanId: event.target.value })} />}</td><td><input value={row.stream_name ?? ""} placeholder="Camera 1" disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { stream_name: event.target.value })} /></td><td><button type="button" className="maintenance-secondary-button protocol-map-profile-button" disabled={locked || state === "saving" || !profiles.length} title={profiles.length ? "Choose one or more alert profiles." : "Create profiles in Alert policies first."} onClick={() => setProfileTargetId(row.id ?? null)}>{profileSummary(assignedProfiles(row.id ?? ""), profiles)}</button>{!profiles.length && <span className="protocol-map-assignment-hint">Create profiles first</span>}</td><td><button type="button" className="maintenance-secondary-button icon-only" disabled={locked || state === "saving"} onClick={() => removeRow(index)} aria-label="Delete Monitoring target" title="Delete Monitoring target"><Icon name="delete" size={16} /></button></td></tr>)}</tbody></table></div><div className="protocol-map-row-actions"><button type="button" className="maintenance-secondary-button button-with-icon" disabled={locked || state === "saving"} onClick={addRow}><Icon name="add" size={16} />Add target</button></div></section>
      {profileTarget && <ProfilePicker target={profileTarget} profiles={profiles} selectedIds={assignedProfiles(profileTarget.id ?? "")} busy={state === "saving"} onToggle={(id) => { const selected = assignedProfiles(profileTarget.id ?? ""); setAssignedProfiles(profileTarget, selected.includes(id) ? selected.filter((selectedId) => selectedId !== id) : [...selected, id]); }} onClear={() => setAssignedProfiles(profileTarget, [])} onClose={() => setProfileTargetId(null)} />}
      </div><footer className="maintenance-actions maintenance-actions-floating"><span className={`maintenance-message maintenance-message-${state}`} role="status">{state === "loading" ? "Loading Monitoring targets…" : message}</span><button type="submit" className="maintenance-save-button button-with-icon" disabled={!settings || state === "loading" || state === "saving"}><Icon name="save" size={16} />{state === "saving" ? "Applying…" : "Apply"}</button></footer>
    </form>
  </PaneFrame>;
}

function alertsDocument(document: AlertsDocument, assignments: AlertAssignment[]): AlertsDocument { return document.rules ? { ...(document._note ? { _note: document._note } : {}), rules: document.rules, profiles: document.profiles ?? [], assignments } : document; }
function toRow(rule: ProtocolRule): Row {
  const endpoint = first(rule.endpoints); const host = first(rule.hosts) || first(rule.domains); const target = host ? "host" : "endpoint"; const split = endpoint ? splitEndpoint(endpoint) : { value: host ?? "", port: "" }; const vlan = rule.vlan === null ? { vlanMode: "untagged" as const, vlanId: "" } : rule.vlan === undefined ? { vlanMode: "any" as const, vlanId: "" } : { vlanMode: "id" as const, vlanId: String(rule.vlan) };
  return { ...rule, id: rule.id || newTargetId(), proto: rule.proto === "RTP" && rule.fec === true ? "RTP-FEC" : rule.proto, target, value: split.value, port: split.port, ...vlan };
}
function fromRow(row: Row): ProtocolRule {
  const { target, value, port, vlanMode, vlanId, proto, ...rule } = row; const next: ProtocolRule = { ...rule, observe: rule.observe ?? true, enabled: rule.enabled !== false, proto: proto === "RTP-FEC" ? "RTP" : proto, ...(vlanMode === "untagged" ? { vlan: null } : vlanMode === "id" ? { vlan: Number(vlanId) } : {}) };
  if (target === "host") next.hosts = [value.trim()]; else next.endpoints = [`${formatHost(value.trim())}:${port}`];
  if (proto === "RTP-FEC") next.fec = true; else delete next.fec;
  if (!next.target_name?.trim()) delete next.target_name;
  if (!next.stream_name?.trim()) delete next.stream_name;
  return next;
}
function newTargetId() { return globalThis.crypto?.randomUUID?.() ?? "target_" + Math.random().toString(36).slice(2) + Date.now().toString(36); }
function first(value: string | string[] | undefined) { return typeof value === "string" ? value : value?.[0] ?? ""; }
function splitEndpoint(endpoint: string) { const ipv6 = endpoint.match(/^\[(.*)]:(\d+)$/); if (ipv6) return { value: ipv6[1], port: ipv6[2] }; const index = endpoint.lastIndexOf(":"); return index > 0 ? { value: endpoint.slice(0, index), port: endpoint.slice(index + 1) } : { value: endpoint, port: "" }; }
function formatHost(value: string) { return value.includes(":") && !value.startsWith("[") ? `[${value}]` : value; }

function profileSummary(ids: string[], profiles: Array<{ id: string; title?: string }>) {
  if (!ids.length) return "Protocol default";
  const names = ids.map((id) => profiles.find((profile) => profile.id === id)?.title || id);
  return names.length === 1 ? names[0] : `${names.length} profiles`;
}

function ProfilePicker({ target, profiles, selectedIds, busy, onToggle, onClear, onClose }: { target: Row; profiles: Array<{ id: string; title?: string; rule_ids: string[] }>; selectedIds: string[]; busy: boolean; onToggle: (id: string) => void; onClear: () => void; onClose: () => void }) {
  const title = target.target_name || target.stream_name || "Monitoring target";
  return <div className="protocol-map-profile-backdrop" role="presentation" onPointerDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section className="protocol-map-profile-picker" role="dialog" aria-modal="true" aria-label={`Alert profiles for ${title}`}><header><div><h2>Alert profiles</h2><p>{title}</p></div><button type="button" className="maintenance-secondary-button" onClick={onClose}>Done</button></header><p className="protocol-map-profile-help">Select profiles to apply to this target. With none selected, the protocol default applies.</p><div className="protocol-map-profile-options">{profiles.map((profile) => <label key={profile.id}><input type="checkbox" checked={selectedIds.includes(profile.id)} disabled={busy} onChange={() => onToggle(profile.id)} /><span>{profile.title || profile.id}</span><small>{profile.title ? profile.id : `${profile.rule_ids.length} rules`}</small></label>)}</div><footer><button type="button" className="maintenance-secondary-button" disabled={busy || !selectedIds.length} onClick={onClear}>Use protocol default</button></footer></section></div>;
}
.alerts-input-unit { position: absolute; top: 50%; right: var(--space-2); transform: translateY(-50%); color: var(--muted); cursor: help; font-size: var(--font-size-xs); line-height: 1; pointer-events: auto; }
.alerts-number-field input[aria-invalid="true"] { border-color: var(--danger); }
.alerts-value-hint { color: var(--muted); cursor: help; font-size: var(--font-size-xs); white-space: nowrap; }
.alerts-profile-rules .alerts-value-hint { display: inline; }

/* Keep Apply available while the settings form itself scrolls. */
.maintenance-floating-actions-frame .pane-body { overflow: hidden; }
.maintenance-form-with-floating-actions { position: relative; height: 100%; min-height: 0; padding: 0; }
.maintenance-form-content { display: grid; height: 100%; min-height: 0; align-content: start; gap: var(--space-4); overflow: auto; padding: var(--space-3); padding-bottom: calc(var(--control-height) + var(--space-6)); }
.maintenance-actions-floating { position: absolute; right: var(--space-3); bottom: var(--space-3); z-index: 4; max-width: calc(100% - (var(--space-3) * 2)); pointer-events: none; }
.maintenance-actions-floating > * { pointer-events: auto; }
.maintenance-actions-floating .maintenance-message { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
@media (max-width: 540px) { .maintenance-actions-floating { left: var(--space-3); } .maintenance-actions-floating .maintenance-message { display: none; } }
.maintenance-actions-floating .maintenance-save-button { box-shadow: 0 5px 14px color-mix(in srgb, var(--accent) 32%, transparent), 0 2px 5px rgba(0, 0, 0, .24); }

