  return <tr><td><button type="button" role="switch" aria-checked={rule.enabled !== false} className={"maintenance-switch " + (rule.enabled !== false ? "is-on" : "is-off")} disabled={busy} onClick={() => onUpdate({ enabled: rule.enabled === false })}>{rule.enabled === false ? "Off" : "On"}</button></td><td><input className="alerts-id-input" value={rule.id} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ id: event.target.value })} /></td><td><select value={target} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ target: event.target.value as AlertRule["target"] })}><option value="flow">Flow</option><option value="stream">Stream</option><option value="interface">Interface</option><option value="any">Any</option></select></td><td><select value={rule.proto ?? ""} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ proto: event.target.value || undefined })}><option value="">Any</option>{protocols.map((proto) => <option key={proto} value={proto}>{proto}</option>)}</select></td><td><input value={roles} disabled={busy || lockedIdentity || target !== "flow"} placeholder="media, data" onChange={(event) => onUpdate({ flow_roles: event.target.value.split(",").map((value) => value.trim()).filter(Boolean) })} data-tooltip-key={rule.proto ? "tooltip.availableRoles" : undefined} data-tooltip-roles={rule.proto ? (flowRoles[rule.proto] ?? []).join(", ") : undefined} /></td><td><select value={rule.indicator_category ?? "other"} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ indicator_category: event.target.value as AlertRule["indicator_category"] })}><option value="other">Other</option><option value="quality">Quality</option></select></td><td><select value={rule.metric} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ metric: event.target.value })}>{!selectableMetrics.some((metric) => metric.key === rule.metric) && <option value={rule.metric}>Current: {rule.metric} (not available for this target)</option>}{selectableMetrics.map((metric) => <option key={metric.key} value={metric.key}>{metric.key}</option>)}</select></td><td><select value={type} disabled={busy || lockedIdentity} onChange={(event) => setType(event.target.value as AlertRule["type"])}><option value="threshold">Threshold</option><option value="counter_delta">Counter delta</option><option value="availability">Availability</option></select>{type !== "availability" && <select value={rule.operator ?? ">"} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ operator: event.target.value as AlertRule["operator"] })}>{operators.map((operator) => <option key={operator} value={operator}>{operator}</option>)}</select>}</td><td>{type === "availability" ? <NumberInput value={rule.inactive_after_sec} disabled={busy} onChange={(inactive_after_sec) => onUpdate({ inactive_after_sec })} /> : <NumberInput value={type === "counter_delta" ? rule.delta_threshold : rule.error_threshold} disabled={busy} onChange={(value) => onUpdate(type === "counter_delta" ? { delta_threshold: value } : { error_threshold: value })} />}</td><td>{type === "availability" ? "Packet received" : <NumberInput value={type === "counter_delta" ? rule.recover_after_sec : rule.recover_threshold} disabled={busy} onChange={(value) => onUpdate(type === "counter_delta" ? { recover_after_sec: value } : { recover_threshold: value })} />}</td><td><TimingFields rule={rule} disabled={busy || lockedIdentity} onUpdate={onUpdate} /></td><td><select value={rule.severity ?? "warning"} disabled={busy} onChange={(event) => onUpdate({ severity: event.target.value })}>{severities.map((severity) => <option key={severity} value={severity}>{severity}</option>)}</select></td><td>{!lockedIdentity && <button type="button" className="maintenance-secondary-button icon-only" disabled={busy} onClick={onRemove} aria-label="Delete condition" data-tooltip-key="tooltip.deleteCondition"><Icon name="delete" size={16} /></button>}</td></tr>;
}

function TimingFields({ rule, disabled, onUpdate }: { rule: AlertRule; disabled: boolean; onUpdate: (patch: Partial<AlertRule>) => void }) {
  if ((rule.type ?? "threshold") === "availability") return <span data-tooltip-key="tooltip.lastPacketEvaluated">Last packet</span>;
  return <span className="alerts-inline-field">{(rule.type ?? "threshold") === "threshold" && <><label>On<NumberInput value={rule.trigger_after_sec} disabled={disabled} onChange={(trigger_after_sec) => onUpdate({ trigger_after_sec })} /></label><label>Off<NumberInput value={rule.recover_after_sec} disabled={disabled} onChange={(recover_after_sec) => onUpdate({ recover_after_sec })} /></label></>}<label>Missing<NumberInput value={rule.missing_after_sec} disabled={disabled} onChange={(missing_after_sec) => onUpdate({ missing_after_sec })} /></label></span>;
}

function NumberInput({ value, disabled, onChange }: { value: number | undefined; disabled: boolean; onChange: (value: number | undefined) => void }) {
  return <input type="number" value={value ?? ""} disabled={disabled} onChange={(event) => onChange(event.target.value === "" ? undefined : Number(event.target.value))} />;
}

export function newAlertCondition(proto: string | undefined, flowRoles: Record<string, string[]>, existing: AlertRule[] = [], defaultFlowRoles?: string[]): AlertRule {
  const roles = defaultFlowRoles ?? (proto === "RTP" ? ["media"] : proto === "SRT" ? ["data"] : undefined);
  return { id: nextId("condition", existing.map((rule) => rule.id)), target: "flow", ...(proto ? { proto } : {}), ...(roles && flowRoles[proto ?? ""] ? { flow_roles: roles } : {}), metric: "bitrate.bps", type: "threshold", operator: "<", error_threshold: 0, recover_threshold: 0, severity: "warning" };
}

function isSelectableMetric(key: string, target: string, proto: string | undefined) {
  const interfaceMetric = key.startsWith("link.") || key.startsWith("rx.") || key.startsWith("tx.");
  if (target === "interface") return interfaceMetric;
  if (interfaceMetric) return false;
  const universal = key.startsWith("bitrate.") || key.startsWith("packet_rate.") || key.startsWith("packet_count.");
  const mediaCommon = universal || key.startsWith("interval.");
  if (!proto) return universal || key.startsWith("duration.");
  if (proto === "HLS") return key.startsWith("hls.preview.");
  const transportShared = key.startsWith("jitter.") || key.startsWith("seq_stats.");
  if (proto === "SRT") return mediaCommon || transportShared || key.startsWith("bandwidth.") || key.startsWith("control_type_count.") || key.startsWith("nak_seqno.") || key.startsWith("packet_breakdown.") || key.startsWith("rate.") || key.startsWith("rcvrate.") || key.startsWith("rtt.") || key.startsWith("rttvar.");
  if (proto === "RTP" || proto === "RTMP") return mediaCommon || transportShared || key.startsWith("clock_skew.");
  return universal;
}

function nextId(prefix: string, ids: string[]) { let index = 1; while (ids.includes(prefix + "-" + index)) index += 1; return prefix + "-" + index; }

