function PoliciesPane({ policies, bindings, targets, metrics, protocols, flowRoles, busy, disclosure, onAdd, onUpdate, onRename, onDelete }: { policies: AlertPolicy[]; bindings: AlertBinding[]; targets: MonitoringTargetDefinition[]; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>; busy: boolean; disclosure: ReturnType<typeof useDisclosurePanel>; onAdd: () => void; onUpdate: (policyId: string, policy: AlertPolicy) => void; onRename: (policyId: string, id: string) => void; onDelete: (policy: AlertPolicy) => void }) {
  return <div className="alerts-common-policies-section"><header className="alerts-common-policies-heading"><p>Open a policy to edit its conditions and review every setting that uses it.</p><button type="button" className="maintenance-secondary-button button-with-icon" disabled={busy} onClick={onAdd}><Icon name="add" size={16} />Add common policy</button></header><div className="maintenance-table-wrap alerts-common-policy-table-wrap"><table className="maintenance-table alerts-common-policy-table"><colgroup><col className="alerts-common-policy-col-index" /><col className="alerts-common-policy-col-title" /><col className="alerts-common-policy-col-id" /><col className="alerts-common-policy-col-count" /><col className="alerts-common-policy-col-count" /><col className="alerts-common-policy-col-action" /></colgroup><thead><tr><th>#</th><th>Common policy</th><th>Policy ID</th><th>Conditions</th><th>Bindings</th><th /></tr></thead><tbody>{policies.map((policy, index) => { const usage = bindings.filter((binding) => binding.policy_id === policy.id); const open = disclosure.isOpen(policy.id); return <Fragment key={policy.id}><tr className="alerts-common-policy-summary-row"><td>{index + 1}</td><td><button type="button" className="alerts-common-policy-title" aria-expanded={open} onClick={() => disclosure.toggle(policy.id)}>{policy.title || policy.id}</button></td><td><code>{policy.id}</code></td><td>{policy.conditions.length}</td><td>{usage.length}</td><td><button type="button" className="maintenance-secondary-button alerts-common-policy-edit-button" aria-expanded={open} onClick={() => disclosure.toggle(policy.id)}>{open ? "Close" : "Edit"}</button></td></tr><tr className="alerts-common-policy-detail-row"><td colSpan={6}><DisclosurePanel open={open} rendered={disclosure.isRendered(policy.id)}><section className="alerts-common-policy-detail"><header><div><h3>Common policy</h3><p>Changes apply to every listed target after saving and restarting STM.</p></div><button type="button" className="maintenance-secondary-button" disabled={busy} onClick={() => onDelete(policy)}>Delete</button></header><div className="alerts-profile-fields"><label>Policy ID<input key={policy.id} defaultValue={policy.id} disabled={busy} onBlur={(event) => onRename(policy.id, event.target.value.trim())} /></label><label>Title<input value={policy.title ?? ""} disabled={busy} onChange={(event) => onUpdate(policy.id, { ...policy, title: event.target.value })} /></label></div><h4>Impact</h4><p>{usage.length ? "Used by " + usage.length + " binding(s): " + usage.map((binding) => bindingLabel(binding, targets)).join(", ") : "Not assigned to any target."}</p><AlertConditionTable title="Common policy conditions" rules={policy.conditions} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy} onChange={(conditions) => onUpdate(policy.id, { ...policy, conditions })} /></section></DisclosurePanel></td></tr></Fragment>; })}{policies.length === 0 && <tr><td colSpan={6} className="alerts-empty">No common policies. Add a policy to define reusable Alert conditions.</td></tr>}</tbody></table></div></div>;
}

function DefaultsPane({ document, protocols, busy, selectedProtocol, onSelect, onDocument }: { document: AlertsDocument; protocols: string[]; busy: boolean; selectedProtocol: string; onSelect: (proto: string) => void; onDocument: (document: AlertsDocument) => void }) {
  const binding = document.bindings.find((item) => item.scope.kind === "protocol" && item.scope.proto === selectedProtocol && (item.scope.target ?? "flow") === "flow");
  const update = (mode: "shared" | "disabled", policyId?: string) => {
    const scope = { kind: "protocol" as const, proto: selectedProtocol, target: "flow" as const };
    onDocument(replaceBinding(document, mode === "disabled" ? { scope, mode } : { scope, mode, ...(policyId ? { policy_id: policyId } : {}) }));
  };
  return <section className="alerts-protocol-defaults"><h2>Protocol defaults</h2><p>These apply only when no higher-priority group or target-specific setting matches. Target-specific policies are managed from each Monitoring target.</p><div className="alerts-profile-fields"><label>Protocol<select value={selectedProtocol} disabled={busy} onChange={(event) => onSelect(event.target.value)}>{protocols.map((proto) => <option key={proto} value={proto}>{proto}</option>)}</select></label><label>Default method<select value={binding?.mode ?? "inherit"} disabled={busy} onChange={(event) => { const value = event.target.value; if (value === "inherit") onDocument(removeBinding(document, { kind: "protocol", proto: selectedProtocol, target: "flow" })); else update(value as "shared" | "disabled", binding?.policy_id ?? document.policies[0]?.id); }}><option value="inherit">No protocol default</option><option value="shared">Common policy only</option><option value="disabled">Alert evaluation disabled</option></select></label>{binding?.mode === "shared" && <label>Common policy<select value={binding.policy_id ?? ""} disabled={busy} onChange={(event) => update("shared", event.target.value)}>{document.policies.map((policy) => <option key={policy.id} value={policy.id}>{policy.title || policy.id}</option>)}</select></label>}</div></section>;
}

function nextId(prefix: string, ids: string[]) { let index = 1; while (ids.includes(prefix + "-" + index)) index += 1; return prefix + "-" + index; }
function bindingLabel(binding: AlertBinding, targets: MonitoringTargetDefinition[]) { if (binding.scope.kind === "protocol") return (binding.scope.proto ?? "All protocols") + " default"; const targetId = binding.scope.target_id; return targets.find((target) => target.id === targetId)?.title || targetId; }
function changedPolicyIds(previous: AlertsDocument, next: AlertsDocument) { const before = new Map(previous.policies.map((policy) => [policy.id, JSON.stringify(policy)])); return next.policies.filter((policy) => before.get(policy.id) !== JSON.stringify(policy)).map((policy) => policy.id); }
