右側のコンテキストInspectorからworkspaceを開く操作は、対象を広く確認するための展開である。しかし従来は独立タブへ移動した後、メニューで元タブを選び直す以外の復帰手段がなく、展開前の画面との操作上の連続性がなかった。

### Decision

import type { AlertMetricDefinition, AlertRule } from "../types/api";
import { Icon } from "./ui/Icon";

const operators = [">", ">=", "<", "<=", "==", "!="] as const;
const severities = ["info", "warning", "error", "critical"];

export function AlertConditionTable({ title, rules, metrics, protocols, flowRoles, busy, onChange, lockedIdentity = false }: { title: string; rules: AlertRule[]; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>; busy: boolean; onChange: (rules: AlertRule[]) => void; lockedIdentity?: boolean }) {
  const update = (index: number, patch: Partial<AlertRule>) => onChange(rules.map((rule, ruleIndex) => ruleIndex === index ? { ...rule, ...patch } : rule));
  const remove = (index: number) => onChange(rules.filter((_, ruleIndex) => ruleIndex !== index));
  const add = () => onChange([...rules, newAlertCondition(undefined, flowRoles, rules)]);
  return <section className="alerts-rules-table-section"><h4>{title}</h4><div className="maintenance-table-wrap"><table className="maintenance-table alerts-table alerts-condition-table"><colgroup><col className="alerts-condition-col-enabled" /><col className="alerts-condition-col-id" /><col className="alerts-condition-col-target" /><col className="alerts-condition-col-protocol" /><col className="alerts-condition-col-roles" /><col className="alerts-condition-col-indicator" /><col className="alerts-condition-col-metric" /><col className="alerts-condition-col-type" /><col className="alerts-condition-col-value" /><col className="alerts-condition-col-value" /><col className="alerts-condition-col-timing" /><col className="alerts-condition-col-severity" /><col className="alerts-condition-col-delete" /></colgroup><thead><tr><th>Enabled</th><th>Condition ID</th><th>Target</th><th>Protocol</th><th>Roles</th><th>Indicator</th><th>Metric</th><th>Type</th><th>Trigger</th><th>Recovery</th><th>Timing</th><th>Severity</th><th /></tr></thead><tbody>{rules.map((rule, index) => <ConditionRow key={rule.id + ":" + index} rule={rule} metrics={metrics} protocols={protocols} flowRoles={flowRoles} busy={busy} lockedIdentity={lockedIdentity} onUpdate={(patch) => update(index, patch)} onRemove={() => remove(index)} />)}{rules.length === 0 && <tr><td colSpan={13} className="alerts-empty">No conditions.</td></tr>}</tbody></table></div>{!lockedIdentity && <div className="protocol-map-row-actions"><button type="button" className="maintenance-secondary-button button-with-icon" disabled={busy} onClick={add}><Icon name="add" size={16} />Add condition</button></div>}</section>;
}

function ConditionRow({ rule, metrics, protocols, flowRoles, busy, lockedIdentity, onUpdate, onRemove }: { rule: AlertRule; metrics: AlertMetricDefinition[]; protocols: string[]; flowRoles: Record<string, string[]>; busy: boolean; lockedIdentity: boolean; onUpdate: (patch: Partial<AlertRule>) => void; onRemove: () => void }) {
  const type = rule.type ?? "threshold";
  const target = rule.target ?? "flow";
  const roles = (rule.flow_roles ?? []).join(", ");
  const selectableMetrics = metrics.filter((metric) => isSelectableMetric(metric.key, target, rule.proto));
  const setType = (next: AlertRule["type"]) => {
    if (next === "availability") onUpdate({ type: next, operator: undefined, error_threshold: undefined, recover_threshold: undefined, delta_threshold: undefined, inactive_after_sec: rule.inactive_after_sec ?? 5 });
    else if (next === "counter_delta") onUpdate({ type: next, operator: rule.operator ?? ">", error_threshold: undefined, recover_threshold: undefined, delta_threshold: rule.delta_threshold ?? 0, recover_after_sec: rule.recover_after_sec ?? 3, inactive_after_sec: undefined });
    else onUpdate({ type: "threshold", operator: rule.operator ?? ">", error_threshold: rule.error_threshold ?? 0, recover_threshold: rule.recover_threshold ?? rule.error_threshold ?? 0, delta_threshold: undefined, inactive_after_sec: undefined });
  };
  return <tr><td><button type="button" role="switch" aria-checked={rule.enabled !== false} className={"maintenance-switch " + (rule.enabled !== false ? "is-on" : "is-off")} disabled={busy} onClick={() => onUpdate({ enabled: rule.enabled === false })}>{rule.enabled === false ? "Off" : "On"}</button></td><td><input className="alerts-id-input" value={rule.id} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ id: event.target.value })} /></td><td><select value={target} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ target: event.target.value as AlertRule["target"] })}><option value="flow">Flow</option><option value="stream">Stream</option><option value="interface">Interface</option><option value="any">Any</option></select></td><td><select value={rule.proto ?? ""} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ proto: event.target.value || undefined })}><option value="">Any</option>{protocols.map((proto) => <option key={proto} value={proto}>{proto}</option>)}</select></td><td><input value={roles} disabled={busy || lockedIdentity || target !== "flow"} placeholder="media, data" onChange={(event) => onUpdate({ flow_roles: event.target.value.split(",").map((value) => value.trim()).filter(Boolean) })} data-tooltip-key={rule.proto ? "tooltip.availableRoles" : undefined} data-tooltip-roles={rule.proto ? (flowRoles[rule.proto] ?? []).join(", ") : undefined} /></td><td><select value={rule.indicator_category ?? "other"} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ indicator_category: event.target.value as AlertRule["indicator_category"] })}><option value="other">Other</option><option value="quality">Quality</option></select></td><td><select value={rule.metric} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ metric: event.target.value })}>{!selectableMetrics.some((metric) => metric.key === rule.metric) && <option value={rule.metric}>Current: {rule.metric} (not available for this target)</option>}{selectableMetrics.map((metric) => <option key={metric.key} value={metric.key}>{metric.key}</option>)}</select></td><td><span className="alerts-condition-type-controls"><select value={type} disabled={busy || lockedIdentity} onChange={(event) => setType(event.target.value as AlertRule["type"])}><option value="threshold">Threshold</option><option value="counter_delta">Counter delta</option><option value="availability">Availability</option></select>{type !== "availability" && <select className="alerts-condition-operator" value={rule.operator ?? ">"} disabled={busy || lockedIdentity} onChange={(event) => onUpdate({ operator: event.target.value as AlertRule["operator"] })}>{operators.map((operator) => <option key={operator} value={operator}>{operator}</option>)}</select>}</span></td><td>{type === "availability" ? <NumberInput value={rule.inactive_after_sec} disabled={busy} onChange={(inactive_after_sec) => onUpdate({ inactive_after_sec })} /> : <NumberInput value={type === "counter_delta" ? rule.delta_threshold : rule.error_threshold} disabled={busy} onChange={(value) => onUpdate(type === "counter_delta" ? { delta_threshold: value } : { error_threshold: value })} />}</td><td>{type === "availability" ? "Packet received" : <NumberInput value={type === "counter_delta" ? rule.recover_after_sec : rule.recover_threshold} disabled={busy} onChange={(value) => onUpdate(type === "counter_delta" ? { recover_after_sec: value } : { recover_threshold: value })} />}</td><td><TimingFields rule={rule} disabled={busy || lockedIdentity} onUpdate={onUpdate} /></td><td><select value={rule.severity ?? "warning"} disabled={busy} onChange={(event) => onUpdate({ severity: event.target.value })}>{severities.map((severity) => <option key={severity} value={severity}>{severity}</option>)}</select></td><td>{!lockedIdentity && <button type="button" className="maintenance-secondary-button icon-only" disabled={busy} onClick={onRemove} aria-label="Delete condition" data-tooltip-key="tooltip.deleteCondition"><Icon name="delete" size={16} /></button>}</td></tr>;
}

function TimingFields({ rule, disabled, onUpdate }: { rule: AlertRule; disabled: boolean; onUpdate: (patch: Partial<AlertRule>) => void }) {
  const type = rule.type ?? "threshold";
  if (type === "availability") return <span data-tooltip-key="tooltip.lastPacketEvaluated">Last packet</span>;
  const summary = [type === "threshold" ? "On " + seconds(rule.trigger_after_sec) : "", type === "threshold" ? "Off " + seconds(rule.recover_after_sec) : "", "Missing " + seconds(rule.missing_after_sec)].filter(Boolean).join(" · ");
  return <details className={"alerts-timing-picker" + (disabled ? " is-disabled" : "")}><summary title={summary} onClick={(event) => { if (disabled) event.preventDefault(); }}><span>{summary}</span></summary><div className="alerts-timing-picker-menu">{type === "threshold" && <label>On<NumberInput value={rule.trigger_after_sec} disabled={disabled} onChange={(trigger_after_sec) => onUpdate({ trigger_after_sec })} /></label>}{type === "threshold" && <label>Off<NumberInput value={rule.recover_after_sec} disabled={disabled} onChange={(recover_after_sec) => onUpdate({ recover_after_sec })} /></label>}<label>Missing<NumberInput value={rule.missing_after_sec} disabled={disabled} onChange={(missing_after_sec) => onUpdate({ missing_after_sec })} /></label></div></details>;
}
function seconds(value: number | undefined) { return value === undefined ? "—" : value + "s"; }

function NumberInput({ value, disabled, onChange }: { value: number | undefined; disabled: boolean; onChange: (value: number | undefined) => void }) {
  return <input type="number" value={value ?? ""} disabled={disabled} onChange={(event) => onChange(event.target.value === "" ? undefined : Number(event.target.value))} />;
